corridor-tms.styles:
:root{
  box-sizing:border-box;
  padding-top:env(safe-area-inset-top,0px);
  padding-bottom:env(safe-area-inset-bottom,0px);
  --bg:#E3E3DF; --panel:rgba(246,246,243,.84); --panel-solid:#F2F2EF; --raised:#FFFFFF; --field:#EDEDE9;
  --line:rgba(27,27,25,.09); --line-2:rgba(27,27,25,.16);
  --ink:#1B1B19; --ink-2:#4F4F4A; --ink-3:#66665F;
  --volt:#EDFA4B; --volt-2:#DCE936; --on-volt:#1B1B19;
  --alert:#B8262E; --alert-soft:#F7DEDE; --ok:#1B6E41; --ok-soft:#DCEFE2; --warn:#8A4F0A; --warn-soft:#F4E5CF;
  --shadow:0 22px 44px -26px rgba(30,30,20,.42), 0 2px 6px -2px rgba(30,30,20,.08);
  --r-panel:26px; --r-card:18px; --r-ctl:12px;
  --ease-out:cubic-bezier(.22,1,.36,1);
  --gap:18px; --rail:76px; --side:364px; --sheet:300px; --top:60px;
  color-scheme:light;
}
@media (prefers-color-scheme: dark){
  :root:not([data-theme="light"]){
    --bg:#1C1D1F; --panel:rgba(38,39,42,.84); --panel-solid:#2A2B2E; --raised:#2C2D31; --field:#35363A;
    --line:rgba(255,255,255,.08); --line-2:rgba(255,255,255,.16);
    --ink:#F1F1EE; --ink-2:#C2C2BC; --ink-3:#A3A39C;
    --alert:#FF7B7F; --alert-soft:#4A2426; --ok:#6BD69F; --ok-soft:#1F3A2B; --warn:#F0B062; --warn-soft:#43331D;
    --shadow:0 22px 44px -24px rgba(0,0,0,.7), 0 2px 6px -2px rgba(0,0,0,.4);
    color-scheme:dark;
  }
}
:root[data-theme="dark"]{
  --bg:#1C1D1F; --panel:rgba(38,39,42,.84); --panel-solid:#2A2B2E; --raised:#2C2D31; --field:#35363A;
  --line:rgba(255,255,255,.08); --line-2:rgba(255,255,255,.16);
  --ink:#F1F1EE; --ink-2:#C2C2BC; --ink-3:#A3A39C;
  --alert:#FF7B7F; --alert-soft:#4A2426; --ok:#6BD69F; --ok-soft:#1F3A2B; --warn:#F0B062; --warn-soft:#43331D;
  --shadow:0 22px 44px -24px rgba(0,0,0,.7), 0 2px 6px -2px rgba(0,0,0,.4);
  color-scheme:dark;
}
*,*::before,*::after{box-sizing:border-box}
[hidden]{display:none!important}
html{height:100%;scroll-padding-top:env(safe-area-inset-top,0px)}
body{margin:0;height:100%;background:var(--bg);color:var(--ink);font-family:'Jost',ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif;font-size:15px;line-height:1.4;-webkit-font-smoothing:antialiased;overflow:hidden;font-variant-numeric:tabular-nums}
button,input,select{font:inherit;color:inherit}
button{cursor:pointer;-webkit-tap-highlight-color:transparent}
h1,h2,h3,p{margin:0}
svg.i{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;flex:none}
svg.i.s{width:18px;height:18px}
:focus-visible{outline:2px solid var(--ink);outline-offset:2px}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.muted{color:var(--ink-3)}
.panel{background:var(--panel);-webkit-backdrop-filter:blur(16px) saturate(1.25);backdrop-filter:blur(16px) saturate(1.25);border:1px solid var(--line);box-shadow:var(--shadow)}

/* ---------- stage ---------- */
.stage{position:fixed;inset:0;z-index:0}
.stage::after{content:'';position:absolute;left:0;right:0;top:0;height:150px;pointer-events:none;background:linear-gradient(to bottom,var(--bg),transparent);opacity:.72}
.stage canvas{display:block;width:100%;height:100%;touch-action:none;cursor:grab}
.stage canvas.grabbing{cursor:grabbing}
.stage canvas.pointing{cursor:pointer}
.gl-fallback{position:absolute;inset:0;display:grid;place-items:center;color:var(--ink-3);padding:24px;text-align:center}
.labels{position:fixed;inset:0;z-index:1;pointer-events:none;overflow:hidden}
.tag{position:absolute;left:0;top:0;display:flex;align-items:center;gap:6px;padding:5px 11px;border-radius:999px;font-size:13px;font-weight:500;white-space:nowrap;background:var(--raised);color:var(--ink);box-shadow:0 6px 16px -8px rgba(0,0,0,.35);will-change:transform;opacity:0;transition:opacity .2s}
.tag.on{opacity:1}
.tag.hub{background:transparent;box-shadow:none;color:var(--ink-2);font-size:12.5px;padding:0;font-weight:500;text-shadow:0 1px 0 var(--bg),0 0 8px var(--bg)}
.tag.volt{background:var(--volt);color:var(--on-volt)}
.tag.red{background:var(--alert);color:#fff}
.tag .dot{width:18px;height:18px;border-radius:50%;display:grid;place-items:center;background:rgba(0,0,0,.12)}
.tag .dot svg{width:12px;height:12px;stroke-width:2.4}

/* ---------- rail ---------- */
.rail{position:fixed;z-index:3;left:var(--gap);top:calc(var(--gap) + env(safe-area-inset-top,0px));bottom:calc(var(--gap) + env(safe-area-inset-bottom,0px));width:var(--rail);border-radius:var(--r-panel);display:flex;flex-direction:column;align-items:center;padding:14px 0;gap:10px}
.logo{width:48px;height:48px;border-radius:16px;background:var(--ink);display:grid;place-items:center;margin-bottom:18px}
.logo svg{width:30px;height:30px}
.rail-items{display:flex;flex-direction:column;gap:8px;flex:1}
.rail-btn{position:relative;width:52px;height:52px;border-radius:17px;border:0;background:transparent;display:grid;place-items:center;color:var(--ink-2);transition:background-color .2s,color .2s}
.rail-btn:hover{background:var(--field);color:var(--ink)}
.rail-btn[aria-current="page"]{background:var(--raised);color:var(--ink);box-shadow:0 8px 18px -10px rgba(0,0,0,.35)}
.rail-btn[aria-current="page"]::before{content:"";position:absolute;left:-12px;top:16px;bottom:16px;width:4px;border-radius:4px;background:var(--volt)}
.rail-btn .tip{position:absolute;left:64px;top:50%;transform:translate(-4px,-50%);background:var(--ink);color:var(--bg);font-size:13px;padding:6px 10px;border-radius:9px;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .15s,transform .15s var(--ease-out)}
.rail-btn:hover .tip,.rail-btn:focus-visible .tip{opacity:1;transform:translate(0,-50%)}
.me{width:44px;height:44px;border-radius:50%;background:var(--field);display:grid;place-items:center;font-weight:600;font-size:14px;color:var(--ink-2)}

/* ---------- top bar ---------- */
.topbar{position:fixed;z-index:4;left:calc(var(--gap)*2 + var(--rail));right:var(--gap);top:calc(var(--gap) + env(safe-area-inset-top,0px));height:var(--top);display:flex;align-items:center;gap:12px}
.title{margin-right:auto;min-width:0;padding-left:6px}
.title h1{font-size:26px;font-weight:600;letter-spacing:-.01em;line-height:1.1;white-space:nowrap}
.sub{display:flex;align-items:center;gap:8px;color:var(--ink-3);font-size:14px;margin-top:3px}
.live-dot{width:8px;height:8px;border-radius:50%;background:var(--ok);box-shadow:0 0 0 0 var(--ok)}
.live-dot.ping{animation:ping 1s var(--ease-out)}
@keyframes ping{from{box-shadow:0 0 0 0 color-mix(in srgb,var(--ok) 60%,transparent)}to{box-shadow:0 0 0 9px transparent}}
.pill{height:48px;border-radius:16px;display:flex;align-items:center;gap:8px;padding:0 14px}
.search{position:relative;width:min(360px,30vw)}
.search input{border:0;background:transparent;outline:0;flex:1;min-width:0;height:100%;font-size:15px}
.search input::placeholder{color:var(--ink-3)}
.search:focus-within{outline:2px solid var(--ink);outline-offset:1px}
kbd{font-family:inherit;font-size:12px;color:var(--ink-3);border:1px solid var(--line-2);border-radius:6px;padding:1px 7px}
.results{position:absolute;top:56px;left:0;right:0;border-radius:18px;padding:6px;display:flex;flex-direction:column;gap:2px;max-height:360px;overflow:auto}
.results button{display:flex;align-items:center;gap:10px;border:0;background:transparent;text-align:left;padding:10px 12px;border-radius:12px}
.results button:hover,.results button.hi{background:var(--field)}
.results .rt{font-weight:500}
.results .rs{color:var(--ink-3);font-size:13px}
.results .empty{padding:12px;color:var(--ink-3);font-size:14px}
.clock{flex-direction:column;align-items:flex-start;justify-content:center;gap:0;line-height:1.15;padding:0 16px}
.clock b{font-weight:600;font-size:16px}
.clock span{font-size:12px;color:var(--ink-3)}
.seg{padding:5px;gap:4px}
.seg button{height:38px;border:0;border-radius:12px;background:transparent;padding:0 12px;color:var(--ink-2);font-weight:500;font-size:14px}
.seg button[aria-pressed="true"]{background:var(--ink);color:var(--bg)}
.icon-pill{width:48px;height:48px;border-radius:16px;display:grid;place-items:center;position:relative;border:1px solid var(--line)}
.badge{position:absolute;top:8px;right:8px;min-width:18px;height:18px;border-radius:9px;background:var(--alert);color:#fff;font-size:11px;font-weight:600;display:grid;place-items:center;padding:0 5px;border:2px solid var(--raised)}
.popover{position:absolute;top:68px;right:0;width:340px;border-radius:20px;padding:14px;z-index:6}
.popover h2{font-size:16px;font-weight:600;margin:2px 4px 10px}

.kpis{position:fixed;z-index:2;left:calc(var(--gap)*2 + var(--rail) + 6px);top:calc(var(--gap) + env(safe-area-inset-top,0px) + var(--top) + 16px);display:flex;gap:8px;flex-wrap:wrap}
.kpi{display:flex;align-items:baseline;gap:8px;padding:8px 14px;border-radius:14px;font-size:14px;color:var(--ink-2)}
.kpi b{font-size:18px;font-weight:600;color:var(--ink)}
.kpi.alert b{color:var(--alert)}

/* ---------- sheet ---------- */
.sheet{position:fixed;z-index:2;left:calc(var(--gap)*2 + var(--rail));right:calc(var(--gap)*2 + var(--side));bottom:calc(var(--gap) + env(safe-area-inset-bottom,0px));height:var(--sheet);border-radius:var(--r-panel);display:flex;flex-direction:column;padding:10px 18px 16px;transition:transform .45s var(--ease-out),height .45s var(--ease-out)}
body[data-view="loads"]{--sheet:min(460px,calc(100svh - 300px))}
.sheet.collapsed{transform:translateY(calc(100% - 64px))}
.handle{position:absolute;top:-14px;left:50%;transform:translateX(-50%);width:76px;height:28px;border-radius:14px;border:1px solid var(--line);background:var(--panel);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);display:grid;place-items:center}
.handle span{width:26px;height:4px;border-radius:2px;background:var(--ink-3);transition:transform .3s}
.sheet-head{display:flex;align-items:center;gap:14px;min-height:42px;margin-bottom:10px}
.sheet-head h2{font-size:18px;font-weight:600}
.sheet-head p{color:var(--ink-3);font-size:14px}
.tools{margin-left:auto;display:flex;gap:4px;background:var(--field);border-radius:12px;padding:4px}
.tools button{border:0;background:transparent;height:32px;padding:0 12px;border-radius:9px;font-size:14px;color:var(--ink-2)}
.tools button[aria-pressed="true"]{background:var(--raised);color:var(--ink);box-shadow:0 2px 6px -3px rgba(0,0,0,.3)}
.sheet-body{flex:1;min-height:0;position:relative}
.view-sec{position:absolute;inset:0;display:none}
.view-sec.on{display:block}
.cards{display:flex;gap:14px;overflow-x:auto;height:100%;padding:2px 2px 6px;scroll-snap-type:x proximity;scrollbar-width:thin}
.card{position:relative;flex:0 0 272px;scroll-snap-align:start;background:var(--raised);border-radius:var(--r-card);border:1px solid var(--line);padding:16px;display:flex;flex-direction:column;gap:12px;overflow:hidden;transition:border-color .2s}
.card:hover{border-color:var(--line-2)}
.card-hit{position:absolute;inset:0;border:0;background:transparent;border-radius:inherit;z-index:1}
.card .z{position:relative;z-index:2}
.card-top{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.card h3{font-size:17px;font-weight:600;line-height:1.2}
.card-top p{font-size:14px;margin-top:2px}
.chip{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:999px;font-size:13px;font-weight:500;white-space:nowrap;background:var(--field);color:var(--ink-2)}
.chip::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
.chip.ok{background:var(--ok-soft);color:var(--ok)}
.chip.warn{background:var(--warn-soft);color:var(--warn)}
.chip.alert{background:var(--alert-soft);color:var(--alert)}
.chip.volt{background:var(--volt);color:var(--on-volt)}
.route{display:grid;grid-template-columns:10px 1fr;gap:2px 10px;font-size:14px;color:var(--ink-2)}
.route i{width:10px;height:10px;border-radius:50%;border:2px solid var(--ink-3);margin-top:5px}
.route i.to{background:var(--ink);border-color:var(--ink)}
.route span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.prog{position:relative;height:22px;margin-top:auto}
.prog-track{position:absolute;left:0;right:0;top:10px;height:3px;border-radius:2px;background:var(--field)}
.prog-fill{position:absolute;inset:0;border-radius:2px;background:var(--ink);transform-origin:left;transform:scaleX(var(--p,0))}
.prog-run{position:absolute;inset:0;transform:translateX(calc(var(--p,0) * 100%))}
.prog-truck{position:absolute;left:0;top:-10px;width:26px;height:22px;transform:translateX(-50%);display:grid;place-items:center;background:var(--raised);border-radius:8px;border:1px solid var(--line-2)}
.prog-truck svg{width:16px;height:16px}
.card-foot{display:flex;justify-content:space-between;align-items:flex-end;margin:0 -16px -16px;padding:12px 16px 14px;border-top:1px solid var(--line);transition:background-color .3s}
.card-foot .k{display:block;font-size:13px;color:var(--ink-3)}
.card-foot strong{font-weight:600;font-size:15px}
.card-foot .big{font-size:24px;line-height:1.1}
.card-foot .r{text-align:right}
.card.is-sel{border-color:transparent;box-shadow:0 0 0 2px var(--ink)}
.card.is-sel .card-foot,.card.is-sel .specs{background:var(--volt);color:var(--on-volt);border-top-color:transparent}
.card.is-sel .card-foot .k,.card.is-sel .specs dt{color:rgba(27,27,25,.66)}
.card.is-late .prog-fill{background:var(--alert)}

/* vehicle cards */
.vcard{flex-basis:258px;padding:0;gap:0}
.vcard .card-top{padding:14px 16px 0}
.vcard .card-top p{font-size:13px;color:var(--ink-3)}
.thumb{height:104px;display:grid;place-items:center;margin:6px 10px 0}
.thumb img{max-width:100%;max-height:100%;display:block}
.specs{margin:0;padding:10px 16px 12px;display:grid;grid-template-columns:auto 1fr;gap:3px 12px;font-size:13.5px;border-top:1px solid var(--line);flex:1;align-content:start;transition:background-color .3s}
.specs dt{color:var(--ink-3)}
.specs dd{margin:0;text-align:right;font-weight:500}
.vacts{display:flex;gap:6px;padding:0 12px 12px;background:inherit}
.card.is-sel .vacts{background:var(--volt)}
.btn{height:36px;border-radius:11px;border:1px solid var(--line-2);background:var(--raised);padding:0 12px;font-size:14px;font-weight:500;display:inline-flex;align-items:center;justify-content:center;gap:6px;white-space:nowrap}
.btn:hover{background:var(--field)}
.btn.primary{background:var(--ink);color:var(--bg);border-color:var(--ink)}
.btn.primary:hover{background:var(--ink);opacity:.9}
.btn.lg{height:48px;padding:0 20px;font-size:15px;border-radius:14px}
.btn.grow{flex:1}

/* rules */
.rule{flex-basis:300px;gap:10px}
.rule-top{display:flex;justify-content:space-between;align-items:center}
.rule .when{font-size:13px;color:var(--ink-3)}
.rule .txt{font-size:15.5px;font-weight:500;line-height:1.35}
.rule .then{padding:10px 12px;border-radius:12px;background:var(--field);font-size:14.5px}
.rule .then b{display:block;font-size:13px;font-weight:400;color:var(--ink-3)}
.rule.off{opacity:.62}
.rule .runs{margin-top:auto;font-size:13px;color:var(--ink-3)}
.stepper{display:inline-flex;align-items:center;gap:2px;vertical-align:middle;background:var(--field);border-radius:10px;padding:2px;margin:0 2px}
.stepper button{width:26px;height:26px;border:0;border-radius:8px;background:var(--raised);display:grid;place-items:center}
.stepper output{min-width:30px;text-align:center;font-weight:600}
.switch{width:46px;height:28px;border-radius:14px;border:0;background:var(--line-2);position:relative;transition:background-color .2s;flex:none}
.switch::after{content:"";position:absolute;top:3px;left:3px;width:22px;height:22px;border-radius:50%;background:var(--raised);transition:transform .25s var(--ease-out)}
.switch[aria-checked="true"]{background:var(--ink)}
.switch[aria-checked="true"]::after{transform:translateX(18px);background:var(--volt)}

/* loads form */
.loads{display:grid;grid-template-columns:1.1fr 1fr;grid-template-rows:auto 1fr;gap:14px;height:100%;overflow:auto;padding:2px}
.drop{grid-row:1;border:1.5px dashed var(--line-2);border-radius:18px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;padding:18px;text-align:center;background:var(--raised);transition:border-color .2s,background-color .2s;min-height:150px}
.drop.over{border-color:var(--ink);background:var(--field)}
.drop .fold{width:40px;height:40px;border-radius:12px;background:var(--field);display:grid;place-items:center;margin-bottom:4px}
.drop p{font-size:15px;font-weight:500}
.drop small{color:var(--ink-3);font-size:13px}
.drop label{margin-top:6px}
.files{display:flex;flex-direction:column;gap:8px;min-height:0;overflow:auto}
.file{display:grid;grid-template-columns:36px 1fr auto;gap:4px 12px;align-items:center;padding:12px 14px;border-radius:16px;background:var(--raised);border:1px solid var(--line)}
.file .pdf{width:34px;height:40px;border-radius:6px;border:1px solid var(--line-2);position:relative;display:grid;place-items:end center;padding-bottom:4px}
.file .pdf b{font-size:9.5px;font-weight:600;color:#fff;background:#C9302C;border-radius:3px;padding:1px 4px}
.file .fn{font-weight:500;font-size:14.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.file .fm{font-size:13px;color:var(--ink-3);display:flex;align-items:center;gap:6px}
.file .fm .okc{color:var(--ok)}
.file .bar{grid-column:1/-1;height:3px;border-radius:2px;background:var(--field);overflow:hidden}
.file .bar i{display:block;height:100%;background:var(--warn);transform-origin:left;transform:scaleX(var(--p,0));transition:transform .15s linear}
.icon-btn{width:34px;height:34px;border-radius:10px;border:0;background:transparent;display:grid;place-items:center;color:var(--ink-3)}
.icon-btn:hover{background:var(--field);color:var(--ink)}
.spin{animation:spin 1s linear infinite;color:var(--warn)}
@keyframes spin{to{transform:rotate(360deg)}}
.fields{grid-column:1/-1;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px 14px;align-items:end}
.field label{display:block;font-size:13.5px;color:var(--ink-2);margin:0 0 6px 2px}
.field input,.field select{width:100%;height:46px;border-radius:13px;border:1px solid transparent;background:var(--field);padding:0 14px;outline:0}
.field input:focus,.field select:focus{border-color:var(--ink)}
.field.err input,.field.err select{border-color:var(--alert)}
.field .em{display:block;color:var(--alert);font-size:12.5px;margin:5px 0 0 2px}
.assign-row{grid-column:1/-1;display:flex;align-items:center;gap:12px;flex-wrap:wrap;position:sticky;bottom:-2px;z-index:1;padding:10px 0 2px;background:linear-gradient(to bottom,transparent,var(--panel-solid,var(--bg)) 14px)}
.assign-row p{color:var(--ink-3);font-size:14px;margin-right:auto}
.assign-row p b{color:var(--ink);font-weight:500}

/* ---------- side ---------- */
.side{position:fixed;z-index:2;right:var(--gap);top:calc(var(--gap) + env(safe-area-inset-top,0px) + var(--top) + 16px);bottom:calc(var(--gap) + env(safe-area-inset-bottom,0px));width:var(--side);border-radius:var(--r-panel);overflow:hidden}
.pane{position:absolute;inset:0;display:flex;flex-direction:column}
.pane[hidden]{display:none}
.pane-scroll{flex:1;overflow:auto;padding:18px}
.ph{display:flex;align-items:center;gap:12px;padding:16px 16px 14px;border-bottom:1px solid var(--line)}
.ph h2{font-size:17px;font-weight:600;line-height:1.2}
.ph p{font-size:13.5px;color:var(--ink-3)}
.ph .grow{flex:1;min-width:0}
.ava{width:44px;height:44px;border-radius:50%;background:var(--field);display:grid;place-items:center;font-weight:600;font-size:14px;position:relative;flex:none}
.ava.sm{width:36px;height:36px;font-size:13px}
.ava .st{position:absolute;right:0;bottom:0;width:11px;height:11px;border-radius:50%;background:var(--ok);border:2px solid var(--raised)}
.ava .st.off{background:var(--ink-3)}
.eta-big{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;margin-bottom:16px}
.eta-big .k{font-size:13.5px;color:var(--ink-3)}
.eta-big strong{display:block;font-size:44px;font-weight:600;line-height:1;letter-spacing:-.02em}
.eta-big .r{text-align:right;font-size:14px;color:var(--ink-2)}
.insight{border-radius:16px;padding:14px;background:var(--alert-soft);color:var(--ink);font-size:14.5px;margin-bottom:16px}
.insight h3{font-size:15px;font-weight:600;color:var(--alert);margin-bottom:4px}
.insight .auto{display:flex;gap:8px;align-items:flex-start;margin-top:10px;padding-top:10px;border-top:1px solid color-mix(in srgb,var(--alert) 22%,transparent);font-size:13.5px;color:var(--ink-2)}
.insight .auto button{border:0;background:none;padding:0;text-decoration:underline;font-weight:500}
.stops{list-style:none;margin:0 0 18px;padding:0;position:relative}
.stops li{display:grid;grid-template-columns:18px 1fr auto;gap:12px;padding:0 0 18px;position:relative}
.stops li:last-child{padding-bottom:0}
.stops li::before{content:"";position:absolute;left:8px;top:18px;bottom:-2px;width:2px;background:var(--line-2)}
.stops li:last-child::before{display:none}
.stops li.done::before{background:var(--ink)}
.stops .pt{width:18px;height:18px;border-radius:50%;border:2px solid var(--line-2);background:var(--raised);margin-top:1px}
.stops li.done .pt{background:var(--ink);border-color:var(--ink)}
.stops li.now .pt{border-color:var(--ink);box-shadow:0 0 0 4px var(--volt)}
.stops b{display:block;font-weight:500}
.stops small{color:var(--ink-3);font-size:13px}
.stops time{font-weight:600}
.facts{display:grid;grid-template-columns:auto 1fr;gap:8px 14px;font-size:14px;margin:0 0 18px}
.facts dt{color:var(--ink-3)}
.facts dd{margin:0;text-align:right}
.pane-foot{padding:12px 16px 16px;border-top:1px solid var(--line);display:flex;flex-direction:column;gap:10px}
.drv{display:flex;align-items:center;gap:12px;padding:12px;border-radius:16px;background:var(--raised);border:1px solid var(--line)}
.drv .grow{flex:1;min-width:0}
.drv b{display:block;font-weight:500}
.drv small{color:var(--ink-3);font-size:13px}

/* chat */
.msgs{flex:1;overflow:auto;padding:16px;display:flex;flex-direction:column;gap:12px}
.msg{max-width:86%;width:fit-content;flex-shrink:0;display:flex;flex-direction:column;gap:4px}
.msg .bub{padding:10px 14px;border-radius:18px;font-size:14.5px;background:var(--raised);border:1px solid var(--line)}
.msg.me{align-self:flex-end;align-items:flex-end}
.msg.me .bub{background:var(--ink);color:var(--bg);border-color:transparent;border-bottom-right-radius:6px}
.msg.them .bub{border-bottom-left-radius:6px}
.msg time{font-size:12px;color:var(--ink-3);padding:0 4px}
.msg .who{font-size:12.5px;color:var(--ink-3);padding:0 4px}
.loc{padding:0;overflow:hidden;width:250px}
.loc p{padding:10px 14px 0}
.loc svg.map{display:block;width:100%;height:110px}
.loc .lchip{display:flex;align-items:center;gap:8px;margin:-40px 10px 10px auto;width:max-content;position:relative;background:var(--raised);border-radius:12px;padding:6px 10px;font-size:13px;box-shadow:0 4px 12px -6px rgba(0,0,0,.3)}
.loc .lchip b{display:block;font-weight:600;font-size:14px;line-height:1.1}
.attach{display:flex;align-items:center;gap:10px}
.typing{display:flex;gap:4px;padding:14px}
.typing i{width:6px;height:6px;border-radius:50%;background:var(--ink-3);animation:bob 1s infinite}
.typing i:nth-child(2){animation-delay:.15s}.typing i:nth-child(3){animation-delay:.3s}
@keyframes bob{50%{transform:translateY(-4px)}}
.composer{margin:0 12px 12px;padding:10px;border-radius:20px;background:var(--volt);display:flex;gap:8px;align-items:center}
.composer input{flex:1;min-width:0;height:44px;border:0;border-radius:13px;background:rgba(255,255,255,.5);padding:0 14px;outline:0;color:#1B1B19}
.composer input::placeholder{color:rgba(27,27,25,.62)}
.composer input:focus{background:rgba(255,255,255,.8)}
.composer .qa{width:44px;height:44px;border-radius:13px;border:0;background:rgba(255,255,255,.5);display:grid;place-items:center;color:#1B1B19}
.composer .qa:hover{background:rgba(255,255,255,.85)}
.composer .qa.send{background:#1B1B19;color:var(--volt)}
.empty-state{padding:24px;color:var(--ink-3);font-size:14.5px}

/* log */
.log{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}
.log li{padding:12px 14px;border-radius:14px;background:var(--raised);border:1px solid var(--line);font-size:14px}
.log li.new{animation:flash 1.6s var(--ease-out)}
@keyframes flash{from{background:var(--volt)}}
.log .lh{display:flex;justify-content:space-between;gap:10px;font-size:13px;color:var(--ink-3);margin-bottom:3px}

/* toasts */
.toasts{position:fixed;z-index:8;bottom:calc(var(--sheet) + var(--gap)*2 + 20px + env(safe-area-inset-bottom,0px));left:calc((var(--gap)*2 + var(--rail) + 100vw - var(--side) - var(--gap)*2) / 2);transform:translateX(-50%);flex-direction:column-reverse;display:flex;flex-direction:column;gap:8px;align-items:center;pointer-events:none;width:min(440px,calc(100vw - 32px))}
.toast{pointer-events:auto;width:100%;display:flex;gap:12px;align-items:flex-start;padding:12px 14px;border-radius:18px;background:var(--ink);color:var(--bg);box-shadow:0 16px 36px -16px rgba(0,0,0,.5)}
.toast .ti{width:30px;height:30px;border-radius:10px;background:var(--volt);color:#1B1B19;display:grid;place-items:center;flex:none}
.toast .tb{flex:1;font-size:14px}
.toast .tb b{display:block;font-weight:600}
.toast .tb span{opacity:.78}
.toast button{border:0;background:rgba(255,255,255,.14);color:inherit;border-radius:10px;height:32px;padding:0 10px;font-size:13.5px;align-self:center}
:root[data-theme="dark"] .toast button{background:rgba(0,0,0,.1)}

/* ---------- small screens ---------- */
@media (max-width: 1180px){
  :root{--side:320px}
  .clock{display:none}
  .search{width:min(280px,28vw)}
}
@media (max-width: 960px){
  body{overflow:auto;height:auto}
  .stage{height:50svh}
  .topbar{left:12px;right:12px;top:calc(10px + env(safe-area-inset-top,0px));height:auto;flex-wrap:wrap;gap:8px}
  .title h1{font-size:22px}
  .search{order:5;flex-basis:100%;width:auto}
  .seg button{padding:0 9px;height:32px;font-size:13px}
  .seg{padding:4px}
  .title{flex:1 1 0;min-width:0}
  .title .sub{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .sheet-head{flex-wrap:wrap;gap:4px 10px}
  .sheet-head .tools{flex-basis:100%;overflow-x:auto}
  .stage::after{height:190px;opacity:.9}
  .kpis,.handle{display:none}
  .rail{top:auto;bottom:calc(10px + env(safe-area-inset-bottom,0px));left:12px;right:12px;width:auto;height:68px;flex-direction:row;padding:8px;z-index:6}
  .logo,.me{display:none}
  .rail-btn .tip{opacity:0!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  .stage canvas{touch-action:pan-y}
  .rail-items{flex-direction:row;justify-content:space-around;width:100%}
  .rail-btn[aria-current="page"]::before{left:18px;right:18px;top:auto;bottom:-6px;height:4px;width:auto}
  .flow{position:relative;z-index:2;padding:calc(50svh - 30px) 12px calc(96px + env(safe-area-inset-bottom,0px))}
  .sheet,.side{position:relative;left:auto;right:auto;top:auto;bottom:auto;width:auto;height:auto;transform:none!important}
  .sheet{min-height:320px}
  body[data-view="loads"] .sheet{height:auto}
  .side{margin-top:12px;height:540px}
  .sheet-body{min-height:250px}
  .view-sec{position:relative}
  .loads{grid-template-columns:1fr;height:auto}
  .fields{grid-template-columns:1fr 1fr}
  .popover{position:fixed;left:12px;right:12px;width:auto;top:120px}
  .toasts{top:auto;left:50%;bottom:calc(92px + env(safe-area-inset-bottom,0px))}
}
@media (prefers-reduced-motion: reduce){
  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
}

