function buildCity(){
  const R = rng(7), blockSize = GRID - 1.9, list = [];
  const plates = new THREE.InstancedMesh(rbox(1, 1, 1, .12), M.plate, 100); plates.receiveShadow = true;
  const dummy = new THREE.Object3D(); let pi = 0;
  const hubSet = new Set(Object.values(HUBS).map(h => h.g.join(',')));
  for (let bi = -5; bi < 5; bi++) for (let bj = -5; bj < 5; bj++){
    const cx = (bi + .5) * GRID, cz = (bj + .5) * GRID;
    dummy.position.set(cx, .06, cz); dummy.scale.set(blockSize + .5, .12, blockSize + .5); dummy.rotation.set(0, 0, 0); dummy.updateMatrix(); plates.setMatrixAt(pi++, dummy.matrix);
    const dist = Math.hypot(cx, cz), park = R() < .1;
