    const split = R(); const cells = split < .35 ? [[0,0,1,1]] : split < .7 ? [[-.25,0,.5,1],[.25,0,.5,1]] : [[-.25,-.25,.5,.5],[.25,-.25,.5,.5],[-.25,.25,.5,.5],[.25,.25,.5,.5]];
