/* ----- camera rig ----- */
const VIEWS3D = {
  live:{t:[0,0,1.5], r:86, pol:.8, az:-.42},
  yard:{t:[140,0,-1], r:64, pol:.92, az:-.5},
  loads:{t:null, r:54, pol:.9, az:-.64},
  auto:{t:[0,0,0], r:104, pol:.6, az:-.12}
};
const rig = {tx:0, ty:0, tz:1.5, r:150, pol:.35, az:-.9, uAz:0, uPol:0, zoom:1, fx:0, fz:0, ox:0, oy:0, oxT:0, oyT:0};
let camTween = null;
function viewTarget(view){
  const v = VIEWS3D[view];
  if (view === 'loads'){ const y = yardById(S.selVeh); return [YO.x + y.slot[0], 0, YO.z + y.slot[1]]; }
  return v.t;
}
function goCam(view, instant){
  if (!GL) return;
  const v = VIEWS3D[view], t = viewTarget(view);
  const st = {tx:rig.tx, tz:rig.tz, r:rig.r, pol:rig.pol, az:rig.az, uAz:rig.uAz, uPol:rig.uPol, zoom:rig.zoom};
  const far = Math.hypot(t[0] - rig.tx, t[2] - rig.tz) > 60;
  const set = k => { rig.tx = lerp(st.tx, t[0], k); rig.tz = lerp(st.tz, t[2], k); rig.r = lerp(st.r, v.r, k) + (far ? Math.sin(k * Math.PI) * 46 : 0); rig.pol = lerp(st.pol, v.pol, k) - (far ? Math.sin(k * Math.PI) * .2 : 0); rig.az = lerp(st.az, v.az, k); rig.uAz = lerp(st.uAz, 0, k); rig.uPol = lerp(st.uPol, 0, k); rig.zoom = lerp(st.zoom, 1, k); };
  camTween && camTween.kill();
  if (instant || reduce()){ set(1); return; }
  const o = {k:0}; camTween = gsap.to(o, {k:1, duration:far ? 1.9 : 1.15, ease:'power3.inOut', onUpdate:() => set(o.k)});
}
function computeOffsets(){
  if (mobile()){ rig.oxT = 0; rig.oyT = 0; return; }
  const cs = getComputedStyle(document.documentElement);
  const side = parseFloat(cs.getPropertyValue('--side')) || 360, rail = 76, gap = 18;
  const sheetH = S.sheetCollapsed ? 64 : $('#sheet').offsetHeight;
  rig.oxT = ((side + gap) - (rail + gap)) / 2;
  rig.oyT = (sheetH + gap) / 2 - 20;
}
function resize(){
  if (!GL) return;
  const w = stage.clientWidth, h = stage.clientHeight;
  renderer.setSize(w, h, false); camera.aspect = w / h; computeOffsets(); camera.updateProjectionMatrix();
}

/* ----- pointer: orbit, hover, pick ----- */
const ray = new THREE.Raycaster(), ndc = new THREE.Vector2();
let drag = null, hover = null;
function pickAt(e){
  const r = canvas.getBoundingClientRect(); ndc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
  ray.setFromCamera(ndc, camera);
  const list = (S.view === 'live' || S.view === 'auto') ? pickNet : pickYard;
  const hit = ray.intersectObjects(list, false)[0];
  return hit ? hit.object.userData.pick : null;
}
function bindPointer(){
  canvas.addEventListener('pointerdown', e => { drag = {x:e.clientX, y:e.clientY, az:rig.uAz, pol:rig.uPol, moved:false}; canvas.setPointerCapture(e.pointerId); });
  canvas.addEventListener('pointermove', e => {
    if (drag){
      const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
      if (Math.abs(dx) + Math.abs(dy) > 4){ drag.moved = true; canvas.classList.add('grabbing'); }
      rig.uAz = clamp(drag.az - dx * .005, -.9, .9); rig.uPol = clamp(drag.pol - dy * .003, -.3, .22); return;
    }
    const p = pickAt(e); hover = p; canvas.classList.toggle('pointing', !!p);
  });
  const end = e => {
    if (!drag) return; canvas.classList.remove('grabbing');
    if (!drag.moved){ const p = pickAt(e); if (p) onPick(p); }
    drag = null;
  };
  canvas.addEventListener('pointerup', end); canvas.addEventListener('pointercancel', () => { drag = null; canvas.classList.remove('grabbing'); });
  canvas.addEventListener('pointerleave', () => { hover = null; canvas.classList.remove('pointing'); });
  canvas.addEventListener('wheel', e => { e.preventDefault(); rig.zoom = clamp(rig.zoom * Math.exp(e.deltaY * .0012), .6, 1.4); }, {passive:false});
}
function onPick(p){
  if (p.type === 'ship'){ if (S.view !== 'live') setView('live'); selectShip(p.id); }
  else if (p.type === 'veh'){ if (yardById(p.id).status !== 'dispatched') selectVeh(p.id); }
  else if (p.type === 'hub'){ if (p.id === 'base') setView('yard'); else toast({icon:'pin', title:HUBS[p.id].name, body:shipsAtHub(p.id)}); }
}
function shipsAtHub(k){ const inb = S.ships.filter(s => s.to === k).length, out = S.ships.filter(s => s.from === k).length; return `${inb} inbound, ${out} outbound right now`; }

/* ----- labels ----- */
const labelsEl = $('#labels'); const tags = new Map();
function tag(key, cls){ let t = tags.get(key); if (!t){ t = document.createElement('div'); labelsEl.appendChild(t); tags.set(key, t); } t._cls = 'tag ' + cls; return t; }
function show(t, on){ const c = t._cls + (on ? ' on' : ''); if (t.className !== c) t.className = c; }
const vtmp = new THREE.Vector3();
function place(t, world){
  vtmp.copy(world).project(camera);
  const vis = vtmp.z < 1 && Math.abs(vtmp.x) < 1.1 && Math.abs(vtmp.y) < 1.1;
  const w = stage.clientWidth, h = stage.clientHeight;
  t.style.transform = `translate(${((vtmp.x + 1) / 2 * w).toFixed(1)}px,${((1 - vtmp.y) / 2 * h).toFixed(1)}px) translate(-50%,-100%)`;
  return vis;
}
function updateLabels(){
  const used = new Set();
  const netOn = (S.view === 'live' || S.view === 'auto'), yardOn = (S.view === 'yard' || S.view === 'loads');
  if (netOn){
    hubMeshes.forEach(h => { const t = tag('hub-' + h.k, 'hub'); if (!t.textContent) t.textContent = HUBS[h.k].name; show(t, place(t, h.pos)); used.add('hub-' + h.k); });
    S.ships.forEach(s => {
      if (!s.g3) return;
      const sel = s.id === S.selShip, late = lateMin(s) >= 5, hov = hover && hover.type === 'ship' && hover.id === s.id;
      if (!sel && !late && !hov) return;
      const key = 'ship-' + s.id, t = tag(key, sel ? 'volt' : late ? 'red' : '');
      const txt = s.state === 'delivered' ? `${s.id}  Delivered` : late ? `${s.id}  ${lateMin(s)} min late` : `${s.id}  ETA ${fmtT(eta(s))}`; if (t.textContent !== txt) t.textContent = txt;
      vtmp.copy(s.g3.truck.group.position); vtmp.y += 1.8;
