  }
  if (yardOn){
    S.yard.forEach(v => {
      const sel = v.id === S.selVeh, rep = v.status === 'repair', hov = hover && hover.type === 'veh' && hover.id === v.id;
      if (!sel && !rep && !hov) return;
      const key = 'veh-' + v.id, t = tag(key, sel ? 'volt' : rep ? 'red' : '');
      const html = sel ? `<span class="dot">${ic('check', '')}</span>Selected` : rep ? `<span class="dot">${ic('alert', '')}</span>Under repair` : `${v.name} ${v.id}`;
      if (t._h !== html){ t.innerHTML = html; t._h = html; }
