}

/* ================= simulation ================= */
function projectedExtra(s){ if (!s.delay || s.state !== 'moving') return 0; const rem = Math.max(0, s.delay.u1 - Math.max(s.p, s.delay.u0)); return rem * s.trip * (1 / SLOW - 1); }
function remainingMin(s){ return s.state === 'delivered' ? 0 : (1 - s.p) * s.trip + projectedExtra(s); }
function eta(s){ return S.simNow + remainingMin(s) * 60000; }
function lateMin(s){ return s.state === 'delivered' ? 0 : Math.round(s.lost + projectedExtra(s)); }
function status(s){
  if (s.state === 'delivered') return ['Delivered', 'ok'];
  const l = lateMin(s); if (l >= 5) return [l + ' min late', 'alert'];
  if (remainingMin(s) <= 15) return ['Arriving soon', 'volt'];
  return ['On time', 'ok'];
}
function addShipment(d){
  const s = Object.assign({lost:0, notified:false, state:'moving', hold:0, pop:1}, d);
  s.curve = buildCurveSafe(s.path); s.len = s.curve.getLength();
  s.departAt = S.simNow - s.p * s.trip * 60000;
  if (!s.via) s.via = viaName(s.path);
  S.ships.push(s);
  if (GL) buildRoute3D(s, S.ships.length);
  return s;
}
function buildCurveSafe(path){ return buildCurve(path); }
function viaName(path){
  let best = null, bl = -1;
  for (let k = 1; k < path.length; k++){ const [a, b] = [path[k - 1], path[k]]; const l = Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]); if (l > bl){ bl = l; best = [a, b]; } }
  return best[0][0] === best[1][0] ? STREET_V[best[0][0] + 5] : STREET_H[best[0][1] + 5];
}
function manhattan(a, b){ const pts = [a]; if (a[0] !== b[0]) pts.push([b[0], a[1]]); if (a[1] !== b[1]) pts.push([b[0], b[1]]); return pts; }
function sim(dt){
  const simMin = dt * S.speed / 60; S.simNow += dt * 1000 * S.speed;
  S.ships.forEach(s => {
    if (s.state === 'moving'){
      let f = 1;
      if (s.delay && s.p >= s.delay.u0 && s.p <= s.delay.u1){ f = SLOW; s.lost += simMin * (1 - SLOW); }
      s.p = Math.min(1, s.p + simMin * f / s.trip);
      const r = rule('late');
      if (S.autoReady && r.on && !s.notified && lateMin(s) >= r.thr){ s.notified = true; s.notifiedAt = S.simNow; fire('late', `Texted ${s.customer} the new arrival time, ${fmtT(eta(s))}`, s.id); }
      if (s.p >= 1){ s.state = 'delivered'; s.hold = 5; arrive(s); }
    } else if (s.state === 'delivered'){
      s.hold -= dt;
      if (s.hold <= 0){ s.state = 'moving'; s.p = 0; s.lost = 0; s.notified = false; s.departAt = S.simNow; s.pop = 0; if (!reduce()) gsap.to(s, {pop:1, duration:.6, ease:'back.out(2)'}); else s.pop = 1; }
    }
  });
}
function arrive(s){
  if (rule('hub').on) fire('hub', `Unloading checklist sent to the ${HUBS[s.to].name} dock team for ${s.id}`, s.id, true);
  if (rule('pod').on) fire('pod', `Asked ${DRIVERS[s.driver].name} for proof of delivery on ${s.id}`, s.id, true);
}
const rule = id => RULES.find(r => r.id === id);
function fire(id, text, ship, quiet){
  const r = rule(id); r.runs++;
  const entry = {t:S.simNow, rule:id, text, ship, fresh:true};
  S.log.unshift(entry); S.log = S.log.slice(0, 40); S.unread++;
  renderLog(); renderRulesRuns(); updateBell();
  if (!quiet || S.view === 'auto') toast({icon:'bolt', title:'Automation ran', body:text, action:ship ? {label:'View', fn:() => { setView('live'); selectShip(ship); }} : null});
  if (S.selShip === ship && S.view === 'live' && S.sideLive === 'detail') renderDetail();
}

/* ================= frame loop ================= */
let last = performance.now(), introK = reduce() ? 1 : 0, uiAcc = 0, pingAcc = 0;
function updateTrucks(t){
  const P = pal();
  S.ships.forEach(s => {
    if (!s.g3) return;
    const {truck, mat, halo} = s.g3; const sel = s.id === S.selShip;
    const pos = s.curve.getPointAt(clamp(s.p, 0, 1)), tan = s.curve.getTangentAt(clamp(s.p, .0001, .9999));
    truck.group.position.set(pos.x, 0, pos.z); truck.group.rotation.y = Math.atan2(-tan.z, tan.x);
    const appear = clamp((introK - .55) / .3, 0, 1) * s.pop;
    truck.group.scale.setScalar(.26 * Math.max(.001, appear) * (sel ? 1.15 : 1));
    const want = sel ? 'sel' : lateMin(s) >= 5 ? 'red' : 'none'; if (truck.tint !== want) setTint(truck, want);
    mat.uniforms.uProg.value = s.p; mat.uniforms.uTime.value = t; mat.uniforms.uReveal.value = clamp(introK * 1.5 - .35, 0, 1) * 1.001;
    mat.uniforms.uRemain.value.setHex(sel ? VOLT : P.routeRemain); mat.uniforms.uAlpha.value = sel ? 1 : .78;
    halo.visible = sel && introK > .6;
  });
  S.yard.forEach(v => {
    const g = v.g3; if (!g) return;
    const sel = v.id === S.selVeh, hov = hover && hover.type === 'veh' && hover.id === v.id;
    const want = sel ? 'sel' : v.status === 'repair' ? 'red' : 'none'; if (g.tint !== want) setTint(g, want);
    g.group.position.y = lerp(g.group.position.y, (hov && !sel) ? .35 : 0, .15);
    g.group.visible = v.status !== 'dispatched';
  });
}
function updateRig(dt){
  let fx = 0, fz = 0;
  if (S.view === 'live'){ const s = shipById(S.selShip); if (s && s.g3){ const p = s.g3.truck.group.position; fx = p.x * .3; fz = p.z * .3; } }
  else if (S.view === 'yard'){ const v = yardById(S.selVeh); if (v){ fx = v.slot[0] * .22; fz = v.slot[1] * .15; } }
  const k = 1 - Math.pow(.02, dt);
  rig.fx = lerp(rig.fx, fx, k); rig.fz = lerp(rig.fz, fz, k); rig.ox = lerp(rig.ox, rig.oxT, k); rig.oy = lerp(rig.oy, rig.oyT, k);
  const aspectBoost = camera.aspect < 1.1 ? 1.45 : 1;
  const R = rig.r * rig.zoom * aspectBoost, pol = clamp(rig.pol + rig.uPol, .25, 1.25), az = rig.az + rig.uAz;
  const tx = rig.tx + rig.fx, tz = rig.tz + rig.fz;
  camera.position.set(tx + R * Math.sin(pol) * Math.sin(az), R * Math.cos(pol), tz + R * Math.sin(pol) * Math.cos(az));
  camera.lookAt(tx, 0, tz);
  const w = stage.clientWidth, h = stage.clientHeight; camera.setViewOffset(w, h, rig.ox, rig.oy, w, h); camera.updateProjectionMatrix();
  sun.position.set(tx + 26, 52, tz + 20); sun.target.position.set(tx, 0, tz); sun.target.updateMatrixWorld();
}
function frame(now){
  const dt = Math.min(.05, (now - last) / 1000); last = now; const t = now / 1000;
  sim(dt);
  if (GL){
    if (introK < 1.0001 && !frame.introDone){ setBlocks(introK); if (introK >= 1) frame.introDone = true; }
    updateTrucks(t);
    hubMeshes.forEach((h, i) => { if (reduce()){ h.ring.scale.setScalar(1.3); h.ring.material.opacity = .22; return; } const ph = (t * .45 + i * .21) % 1; h.ring.scale.setScalar(1 + ph * 2.2); h.ring.material.opacity = .42 * (1 - ph) * clamp(introK * 2 - 1, 0, 1); });
    updateRig(dt);
    renderer.render(scene, camera);
    updateLabels();
  }
  uiAcc += dt; if (uiAcc > .25){ uiAcc = 0; uiTick(); }
  pingAcc += dt; if (pingAcc > 4){ pingAcc = 0; S.lastPing = now; const d = $('#liveDot'); d.classList.remove('ping'); void d.offsetWidth; d.classList.add('ping'); }
  requestAnimationFrame(frame);
}

