function pushMsg(k, m){ chatFor(k).push(m); if (S.chatDriver === k){ const box = $('#msgs'); if (!box) return; box.insertAdjacentHTML('beforeend', msgHTML(m)); if (!reduce()) gsap.from(box.lastElementChild, {y:10, opacity:0, duration:.3, ease:'power2.out'}); box.scrollTop = box.scrollHeight; } }
function driverReply(k, text, kind){
