function summary(){ const v = yardById($('#fVeh').value) || yardById(S.selVeh); const from = HUBS[$('#fFrom').value], to = HUBS[$('#fTo').value]; $('#assignSummary').innerHTML = v ? `<b>${v.name} ${v.id}</b> from <b>${from.name}</b> to <b>${to.name}</b>` : ''; }
let fileTimer = null;
function renderFiles(){
  $('#files').innerHTML = S.files.map((f, i) => `
    <div class="file" data-file="${i}">
      <span class="pdf"><b>${f.ext}</b></span>
      <div style="min-width:0"><div class="fn">${esc(f.name)}</div><div class="fm">${f.state === 'done' ? `${f.size} KB <span class="okc">${ic('check')}</span>Uploaded` : `<span data-kb>${Math.round(f.done)}</span> of ${f.size} KB <span class="spin">${ic('spin')}</span>Uploading`}</div></div>
      <button type="button" class="icon-btn" data-act="rm-file" data-i="${i}" aria-label="${f.state === 'done' ? 'Delete' : 'Cancel upload of'} ${esc(f.name)}">${ic(f.state === 'done' ? 'trash' : 'x')}</button>
      ${f.state === 'done' ? '' : `<div class="bar"><i style="--p:${(f.done / f.size).toFixed(3)}"></i></div>`}
    </div>`).join('') || '<p class="empty-state" style="padding:12px">No documents yet. Add the signed contract and delivery manifest.</p>';
  if (S.files.some(f => f.state !== 'done') && !fileTimer) fileTimer = setInterval(stepUploads, 140);
}
function stepUploads(){
  let changed = false;
  S.files.forEach((f, i) => {
    if (f.state === 'done') return;
    f.done = Math.min(f.size, f.done + Math.max(1.5, f.size * .035) * (.5 + Math.random()));
    const row = $(`[data-file="${i}"]`);
    if (f.done >= f.size){ f.state = 'done'; changed = true; }
    else if (row){ row.querySelector('[data-kb]').textContent = Math.round(f.done); row.querySelector('.bar i').style.setProperty('--p', (f.done / f.size).toFixed(3)); }
  });
  if (changed) renderFiles();
  if (!S.files.some(f => f.state !== 'done')){ clearInterval(fileTimer); fileTimer = null; }
}
function addFiles(list){
  [...list].forEach(file => {
    const ext = (file.name.split('.').pop() || '').toUpperCase();
    if (!['PDF', 'PNG', 'JPG', 'JPEG'].includes(ext)){ toast({icon:'alert', title:`${file.name} can't be added`, body:'Use a JPEG, PNG or PDF file.'}); return; }
    if (file.size > 50 * 1024 * 1024){ toast({icon:'alert', title:`${file.name} is too large`, body:'Files can be up to 50 MB.'}); return; }
    S.files.push({name:file.name, ext:ext === 'JPEG' ? 'JPG' : ext, size:Math.max(1, Math.round(file.size / 1024)), done:0, state:'uploading'});
  });
  renderFiles();
}
