  const id = 'SH-' + (S.nextShip++);
  addShipment({id, customer:$('#fCust').value.trim(), from, to, path, driver:dk, vehicle:v.id, model:v.model, vname:v.name, cargo:S.files.length + ' documents attached', trip:blocks * 4 + 8, p:0});
  v.status = 'dispatched';
