/* ----- toasts ----- */
function toast({icon = 'bolt', title, body, action}){
  const el = document.createElement('div'); el.className = 'toast'; el.setAttribute('role', 'status');
  el.innerHTML = `<span class="ti">${ic(icon)}</span><div class="tb"><b>${esc(title)}</b><span>${esc(body)}</span></div>${action ? `<button type="button">${esc(action.label)}</button>` : ''}`;
  if (action) el.querySelector('button').onclick = () => { action.fn(); kill(); };
  $('#toasts').prepend(el);
  const kids = $$('#toasts .toast'); kids.slice(3).forEach(k => k.remove());
  if (!reduce()) gsap.from(el, {y:-14, opacity:0, duration:.35, ease:'power3.out'});
  let timer = setTimeout(kill, 5200);
  el.addEventListener('mouseenter', () => clearTimeout(timer)); el.addEventListener('mouseleave', () => { timer = setTimeout(kill, 2400); });
  function kill(){ clearTimeout(timer); if (reduce()) return el.remove(); gsap.to(el, {opacity:0, y:-8, duration:.22, ease:'power2.in', onComplete:() => el.remove()}); }
}

