  ['semi-dry', 'semi-reefer', 'semi-flatbed', 'box', 'van'].forEach(k => {
    const v = makeVehicle(k); allVehicles.pop();
    v.mats.body.color.setHex(0xd9d9d6); v.mats.dark.color.setHex(0x8a8a86); v.mats.glass.color.setHex(0x9fa1a4);
    ts.add(v.group); const L = v.len;
    cam.position.set(L * .45, L * .3 + 1.5, L * 1.25); cam.lookAt(0, v.height * .42, 0);
    tr.render(ts, cam); THUMBS[k] = tr.domElement.toDataURL('image/png'); ts.remove(v.group);
  });
  tr.dispose(); tr.forceContextLoss && tr.forceContextLoss();
}

/* ================= boot ================= */
S.yard = YARD_SEED.map(v => Object.assign({}, v));
S.files = [{name:'signed_contract.pdf', ext:'PDF', size:120, done:20, state:'uploading'}, {name:'delivery_manifest.pdf', ext:'PDF', size:94, done:94, state:'done'}];
GL = typeof THREE !== 'undefined' && initGL();
SHIP_SEED.forEach(d => addShipment(Object.assign({}, d)));
const n0 = S.simNow;
S.log = [
  {t:n0 - 16 * 60000, rule:'pod', text:'Asked Robert Fox for proof of delivery on SH-2179', ship:null},
  {t:n0 - 17 * 60000, rule:'hub', text:'Unloading checklist sent to the Central Base dock team for SH-2179', ship:null},
  {t:n0 - 38 * 60000, rule:'late', text:'Texted Tallis Pharma the new arrival time, ' + fmtT(n0 - 20 * 60000), ship:null},
  {t:n0 - 64 * 60000, rule:'pod', text:'Asked Leslie Alexander for proof of delivery on SH-2168', ship:null}
];
if (GL){ makeThumbs(); bindPointer(); resize(); }
fillHubs(); fillVehSelect(); renderFiles(); renderLog(); updateBell(); kpis(); $('#fleetClock').textContent = fmtT(S.simNow);
S.view = '';
setView('live');
document.body.dataset.ready = '1';
setTimeout(() => { S.autoReady = true; }, 3800);
if (GL){
  if (reduce()){ introK = 1; goCam('live', true); }
  else {
    Object.assign(rig, {r:170, pol:.3, az:-1.0});
    goCam('live');
    const o = {k:0}; gsap.to(o, {k:1, duration:2.4, ease:'power2.out', onUpdate:() => { introK = o.k; }});
  }
}
if (!reduce()){
  gsap.from('.rail', {x:-24, opacity:0, duration:.7, ease:'power3.out', delay:.9});
  gsap.from('.topbar > *', {y:-14, opacity:0, duration:.6, ease:'power3.out', stagger:.06, delay:1.0});
  gsap.from('.kpi', {y:-10, opacity:0, duration:.5, ease:'power3.out', stagger:.06, delay:1.5});
  gsap.from('.sheet', {y:40, opacity:0, duration:.8, ease:'power3.out', delay:1.2, clearProps:'transform,opacity'});
  gsap.from('.side', {x:40, opacity:0, duration:.8, ease:'power3.out', delay:1.3, clearProps:'transform,opacity'});
}
requestAnimationFrame(t => { last = t; requestAnimationFrame(frame); });
})();

malayali-kada.styles:
:root{
  --leaf:#213B29; --leaf-deep:#1B3022; --leaf-top:#203A28;
  --rice:#F8F6EF; --paper:#FFFFFF; --coconut:#E6F493; --yellow:#FFD247;
  --curry:#99B97F; --coffee:#5B3A29; --chilli:#B23A20;
  --ink:#1B1B1B; --mute:#5C5A4E; --line:#E3E0D4; --line-dark:rgba(248,246,239,.16);
  --r:22px; --maxw:1280px; --pad:48px; --spine:200px;
  --ease:cubic-bezier(.22,.61,.36,1);
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{background:var(--rice);color:var(--ink);font-family:"Bricolage Grotesque",system-ui,sans-serif;font-size:18px;line-height:1.6;font-variation-settings:"opsz" 14;-webkit-font-smoothing:antialiased}
img,video{display:block;max-width:100%;height:auto}
a{color:inherit}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 var(--pad)}
.ml{font-family:"Manjari",sans-serif}

/* spine */
.row{display:grid;grid-template-columns:var(--spine) minmax(0,1fr);gap:56px;align-items:start}
.lab{font-size:14px;font-weight:500;color:var(--mute);padding-top:14px;display:flex;gap:10px;align-items:center;line-height:1.3}
.lab::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--curry);flex:none}
.dark .lab{color:rgba(248,246,239,.66)} .dark .lab::before{background:var(--yellow)}
section{padding:140px 0}
.tight{padding:96px 0}
h2{font-size:clamp(32px,4vw,52px);line-height:1.08;font-weight:700;letter-spacing:-.02em;font-variation-settings:"opsz" 72;max-width:22ch}
h2 .lt,.mw .lt{font-weight:300;color:var(--mute)}
.dark h2 .lt,.dark .mw .lt{color:rgba(248,246,239,.55)}
h3{font-size:24px;line-height:1.2;font-weight:700;letter-spacing:-.01em;font-variation-settings:"opsz" 36}
p{max-width:64ch}
.body{margin-top:28px;color:#33322C}
.body p+p{margin-top:16px}
.dark{background:var(--leaf);color:var(--rice)}
.dark .body{color:rgba(248,246,239,.84)}
.cap{font-size:14px;line-height:1.45;color:var(--mute);margin-top:12px;max-width:60ch}
.dark .cap{color:rgba(248,246,239,.6)}
.frame{border-radius:var(--r);overflow:hidden;background:var(--paper);border:1px solid var(--line)}
.tag{display:inline-block;font-size:12px;font-weight:500;padding:4px 10px;border-radius:999px;background:var(--coconut);color:var(--leaf)}
.tag.gen{background:#fff;border:1px solid var(--line);color:var(--mute)}
.todo{display:inline-block;font-size:13px;font-weight:500;padding:6px 12px;border-radius:10px;border:1.5px dashed #C9A300;background:#FFF6CC;color:#5A4600}

/* hero */
.hero{background:linear-gradient(180deg,var(--leaf-top) 0%,var(--leaf-deep) 100%);color:var(--rice);position:relative;overflow:hidden;padding:0}
.hero .top{display:flex;justify-content:space-between;align-items:center;padding-top:28px}
.hero .top img{width:52px}
.chips{display:flex;gap:8px;flex-wrap:wrap}
.chip{font-size:13px;font-weight:500;padding:6px 14px;border-radius:999px;border:1px solid rgba(248,246,239,.28);color:rgba(248,246,239,.9)}
.chip.live{background:var(--yellow);color:var(--leaf);border-color:var(--yellow)}
.hero-in{position:relative;z-index:2;padding-top:64px;padding-bottom:28px}
.title{font-size:clamp(64px,11vw,168px);line-height:.9;font-weight:800;letter-spacing:-.045em;font-variation-settings:"opsz" 96}
.title-ml{font-size:clamp(28px,4vw,52px);color:var(--yellow);margin-top:18px;line-height:1.2}
.summary{font-size:20px;color:rgba(248,246,239,.8);margin-top:18px;max-width:46ch}
.hook{margin-top:40px;font-size:clamp(24px,2.6vw,34px);line-height:1.3;letter-spacing:-.01em;max-width:34ch;font-variation-settings:"opsz" 36}
.hook .w{transition:opacity .5s var(--ease)}
.hook b{font-weight:700;color:var(--rice)}
.hook .lt{font-weight:300;color:rgba(248,246,239,.6)}
.byline{margin-top:28px;font-size:15px;color:rgba(248,246,239,.66)}
.byline strong{color:var(--rice);font-weight:600}
.scene{position:relative;height:clamp(150px,20vw,280px)}
.sun{position:absolute;right:12%;bottom:30%;width:clamp(150px,24vw,340px);aspect-ratio:1;border-radius:50%;
  background:repeating-conic-gradient(from 0deg,#FFD247 0 13deg,#FFE58C 13deg 15deg);
  box-shadow:0 0 0 12px rgba(255,210,71,.10),0 0 0 28px rgba(255,210,71,.05);transform:translateY(0);z-index:1}
.js .sun{transform:translateY(90%);opacity:0}
.js.ready .sun{transform:translateY(0);opacity:1;transition:transform 2.6s var(--ease) .2s,opacity 1.2s ease .2s}
.field{position:absolute;left:0;right:0;bottom:0;z-index:2;width:100%;height:auto}
.field img{width:100%;min-width:900px;object-fit:cover;object-position:center}

/* glance */
.glance{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 56px}
.kv{display:grid;grid-template-columns:130px 1fr;gap:16px;padding:18px 0;border-top:1px solid var(--line);font-size:16px;line-height:1.5}
.kv dt{color:var(--mute);font-weight:500}
.kv dd b{font-weight:600}

/* name */
.name-ml{font-size:clamp(72px,12vw,180px);line-height:1;color:var(--leaf);letter-spacing:-.01em}
.defs{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:36px}
.def{background:var(--paper);border:1px solid var(--line);border-radius:var(--r);padding:28px}
.def .w{font-size:28px;font-weight:700}
.def .ml{font-size:22px;color:var(--curry);margin-left:6px}
.def p{margin-top:10px;font-size:16px;color:var(--mute)}

/* evidence strip */
.steps4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;margin-top:56px}
.step4 .ph{aspect-ratio:3/4;border-radius:var(--r);overflow:hidden;background:#EAE7DC;border:1px solid var(--line)}
.step4 .ph img{width:100%;height:100%;object-fit:cover}
.step4 .ph.txt{display:flex;align-items:flex-end;padding:24px;background:var(--coconut);border:0}
.step4 .ph.txt span{font-size:22px;line-height:1.25;font-weight:700;color:var(--leaf)}
.step4 h3{font-size:17px;margin-top:14px}
.step4 p{font-size:15px;color:var(--mute);margin-top:4px}
.limits{margin-top:48px;display:grid;grid-template-columns:1fr 1fr;gap:24px}
.limits div{border-top:2px solid var(--leaf);padding-top:16px;font-size:16px}
.limits h3{font-size:18px;margin-bottom:6px}

/* turn */
.turn{padding:160px 0}
.quote{font-size:clamp(34px,4.6vw,64px);line-height:1.1;letter-spacing:-.025em;font-variation-settings:"opsz" 96;max-width:20ch}
.quote b{font-weight:800;color:var(--yellow)}
.quote .lt{font-weight:300;color:rgba(248,246,239,.72)}
.turn .under{margin-top:36px;font-size:18px;color:rgba(248,246,239,.78);max-width:52ch}

/* jar */
.race{margin-top:48px;display:grid;gap:18px}
.lane{display:grid;grid-template-columns:190px 1fr;gap:20px;align-items:center;font-size:15px}
.lane .bar{height:44px;border-radius:12px;position:relative;display:flex;align-items:center;padding:0 14px;font-size:14px;font-weight:500}
.lane.app .bar{width:6%;min-width:64px;background:#E3E0D4;color:var(--mute)}
.lane.mk .bar{background:var(--leaf);color:var(--rice);gap:0;padding:0}
.lane.mk .seg{flex:1;height:100%;display:flex;align-items:center;justify-content:center;border-right:1px solid rgba(248,246,239,.18);font-size:13px;text-align:center;line-height:1.2;padding:0 6px}
.lane.mk .seg:last-child{border-right:0}
.tl{position:relative;margin-top:72px;padding-left:44px}
.tl .rail{position:absolute;left:11px;top:6px;bottom:6px;width:3px;border-radius:3px;background:var(--line)}
.tl .fill{position:absolute;left:11px;top:6px;width:3px;border-radius:3px;background:var(--leaf);height:100%;transform-origin:top}
.js .tl .fill{transform:scaleY(0)}
.ev{position:relative;padding:0 0 56px;display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:40px;align-items:start}
.ev:last-child{padding-bottom:0}
.ev::before{content:"";position:absolute;left:-41px;top:8px;width:19px;height:19px;border-radius:50%;background:var(--rice);border:3px solid var(--leaf);transition:background .4s}
.ev.on::before{background:var(--yellow)}
.ev .n{font-size:14px;font-weight:500;color:var(--mute)}
.ev h3{margin-top:4px;max-width:30ch}
.ev p{margin-top:8px;font-size:16px;color:#3E3D35}
.ev .media{border-radius:16px;overflow:hidden;border:1px solid var(--line);background:#000}
.ev .media.light{background:var(--paper)}

/* tradeoffs */
.pcard{margin-top:48px;background:var(--leaf);color:var(--rice);border-radius:var(--r);padding:32px 36px;max-width:720px;position:relative}
.pcard .k{font-size:14px;color:var(--yellow);font-weight:500}
.pcard p{font-size:24px;line-height:1.3;font-weight:500;margin-top:8px}
.branch{position:relative;height:56px;max-width:100%}
.branch svg{width:100%;height:100%}
.opts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}
.opt{background:var(--paper);border:1px solid var(--line);border-radius:var(--r);padding:24px;display:flex;flex-direction:column;gap:12px}
.opt .k{font-size:13px;font-weight:600;color:var(--chilli)}
.opt h3{font-size:19px;line-height:1.25}
.opt dl{font-size:14px;line-height:1.45;display:grid;gap:8px;margin-top:4px}
.opt dt{font-weight:600;color:var(--leaf)}
.opt dd{color:#3E3D35}
.withheld{margin-top:28px;border:1.5px dashed #B9B39E;border-radius:var(--r);padding:26px 28px;display:grid;grid-template-columns:220px 1fr;gap:28px;align-items:start}
.withheld .list{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
.withheld .list span{font-size:13px;padding:5px 12px;border-radius:999px;background:#EDEAE0;color:var(--mute);text-decoration:line-through;text-decoration-color:rgba(92,90,78,.45)}
.withheld p{font-size:16px}

/* mark */
.routes{display:grid;grid-template-columns:1fr 1fr 1fr 1.25fr;gap:18px;margin-top:48px;align-items:stretch}
.route{background:var(--paper);border:1px solid var(--line);border-radius:var(--r);padding:22px;display:flex;flex-direction:column;gap:14px}
.route .im{flex:1;display:flex;align-items:center;justify-content:center;min-height:170px}
.route .im img{max-height:160px;width:auto;object-fit:contain}
.route.dead .im{opacity:.8;filter:grayscale(.35)}
.route .k{font-size:13px;font-weight:600;color:var(--mute)}
.route p{font-size:14px;color:#3E3D35;line-height:1.45}
.route.final{background:var(--leaf);color:var(--rice);border-color:var(--leaf)}
.route.final .k{color:var(--yellow)} .route.final p{color:rgba(248,246,239,.85)}
.route.final .im img{max-height:190px}
.eq{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-top:40px;background:var(--paper);border:1px solid var(--line);border-radius:var(--r);padding:28px 32px}
.eq figure{display:flex;flex-direction:column;align-items:center;gap:8px;font-size:13px;color:var(--mute);text-align:center}
.eq figure img{height:70px;width:auto;object-fit:contain}
.eq .op{font-size:34px;font-weight:300;color:var(--curry)}
.eq .res img{height:96px}

/* decisions */
.dec{padding:120px 0;border-top:1px solid var(--line)}
.dec .num{font-size:clamp(96px,11vw,160px);line-height:.8;font-weight:800;color:#EAE7DA;letter-spacing:-.05em;font-variation-settings:"opsz" 96}
.dec .body p{font-size:17px}
.shot{margin-top:44px}
.pair{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px;align-items:start;margin-top:44px}
.pair .frame img{width:100%}
.zones{margin-top:44px;background:var(--paper);border:1px solid var(--line);border-radius:var(--r);padding:28px}
.ruler{position:relative;height:74px;margin:6px 10px 18px}
.ruler .axis{position:absolute;left:0;right:0;top:34px;height:2px;background:var(--line)}
.ruler .tick{position:absolute;top:0;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:6px;background:none;border:0;cursor:pointer;font:inherit;color:var(--mute);font-size:13px}
.ruler .tick i{width:18px;height:18px;border-radius:50%;border:3px solid var(--leaf);background:var(--paper);margin-top:25px;order:2;transition:transform .25s var(--ease),background .25s}
.ruler .tick span{order:1;white-space:nowrap;position:absolute;top:0}
.ruler .tick em{order:3;font-style:normal;font-size:12px;white-space:nowrap}
.ruler .tick.on i{background:var(--yellow);transform:scale(1.25)}
.ruler .tick:focus-visible{outline:2px solid var(--leaf);outline-offset:4px;border-radius:8px}
.zcaps{display:grid;gap:12px}
.zcap{border-radius:12px;overflow:hidden;border:1px solid var(--line)}
.js .zcaps .zcap{display:none}
.js .zcaps .zcap.on{display:block;animation:zin .35s var(--ease)}
@keyframes zin{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.zcap figcaption{font-size:14px;padding:10px 14px;background:#FBFAF6;color:var(--mute)}
.zcap figcaption b{color:var(--ink);font-weight:600}
.trio{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px;margin-top:24px}
.trio .frame img{width:100%;height:100%;object-fit:cover;aspect-ratio:4/5}
.wa{display:grid;grid-template-columns:260px 260px 1fr;gap:18px;margin-top:44px;align-items:start}
.wa .frame{background:#111}
.wa .stack{display:grid;gap:18px}

/* craft */
.cf{position:relative;margin-top:48px}
.cf-track{display:flex;gap:28px;overflow-x:auto;scroll-snap-type:x mandatory;padding:40px calc(50% - 150px);perspective:1200px;scrollbar-width:none}
.cf-track::-webkit-scrollbar{display:none}
.cf-card{flex:0 0 300px;scroll-snap-align:center;border-radius:var(--r);overflow:hidden;transform-style:preserve-3d;transition:transform .15s linear;box-shadow:0 30px 60px -30px rgba(27,48,34,.35);background:var(--paper)}
.cf-card img{width:100%;aspect-ratio:2/3;object-fit:cover}
.cf-card figcaption{padding:12px 16px;font-size:15px;font-weight:600}
.cf-card figcaption span{display:block;font-weight:400;font-size:13px;color:var(--mute)}
.cf-nav{display:flex;gap:10px;justify-content:center;margin-top:8px}
.cf-nav button{width:48px;height:48px;border-radius:50%;border:1px solid var(--line);background:var(--paper);font-size:20px;cursor:pointer;color:var(--leaf)}
.cf-nav button:focus-visible{outline:2px solid var(--leaf);outline-offset:3px}
.palette{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-top:40px}
.sw{border-radius:18px;padding:18px;min-height:150px;display:flex;flex-direction:column;justify-content:space-between;border:1px solid rgba(0,0,0,.06)}
.sw .nm{font-size:16px;font-weight:700;line-height:1.2}
.sw .hx{font-size:13px;opacity:.8}
.sw .ck{font-size:12px;font-weight:500;margin-top:10px;display:flex;gap:6px;flex-wrap:wrap}
.sw .ck span{padding:3px 8px;border-radius:999px;background:rgba(255,255,255,.55);color:#1B1B1B}
.sw .ck span.no{background:rgba(178,58,32,.14);color:#7A2412}
.masonry{columns:4 220px;column-gap:16px;margin-top:40px}
.masonry figure{break-inside:avoid;margin-bottom:16px;border-radius:16px;overflow:hidden;border:1px solid var(--line);background:#EAE7DC}

/* live */
.live{position:relative}
.live .sticky{position:sticky;top:6vh;height:88vh;display:flex;flex-direction:column;justify-content:center}
.browser{border-radius:18px;overflow:hidden;background:#fff;border:1px solid var(--line-dark);box-shadow:0 40px 80px -40px rgba(0,0,0,.6);max-width:1080px;margin:0 auto;width:100%}
.chrome{display:flex;align-items:center;gap:8px;padding:12px 16px;background:#F1EFE7;border-bottom:1px solid var(--line)}
.chrome i{width:11px;height:11px;border-radius:50%;background:#D8D4C6}
.chrome .url{margin-left:12px;flex:1;background:#fff;border-radius:8px;padding:5px 12px;font-size:13px;color:var(--mute)}
.chrome a{font-size:13px;font-weight:600;text-decoration:none;background:var(--yellow);color:var(--leaf);padding:6px 12px;border-radius:8px}
.chrome a:focus-visible{outline:2px solid var(--leaf);outline-offset:2px}
.vp{height:min(62vh,640px);overflow:hidden;position:relative}
.no-js .vp,.rm .vp{overflow:auto}
.vp img{width:100%;will-change:transform}
.prog{height:3px;background:var(--yellow);transform-origin:left;transform:scaleX(0)}

/* concepts */
.strip{display:flex;gap:18px;overflow-x:auto;scroll-snap-type:x mandatory;padding:8px var(--pad) 24px;margin-top:44px;scrollbar-width:thin}
.strip figure{flex:0 0 auto;scroll-snap-align:start;position:relative}
.strip img{height:clamp(260px,34vw,420px);width:auto;border-radius:var(--r)}
.strip .tag{position:absolute;left:14px;top:14px}

/* outcome */
.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;margin-top:48px;border-top:1px solid var(--line-dark)}
.stat{padding:28px 24px 28px 0;border-bottom:1px solid var(--line-dark)}
.stat .v{font-size:clamp(44px,5vw,72px);line-height:1;font-weight:800;letter-spacing:-.03em;color:var(--yellow);font-variation-settings:"opsz" 96}
.stat .l{font-size:16px;margin-top:10px;color:var(--rice);font-weight:500}
.stat .s{font-size:13px;margin-top:6px;color:rgba(248,246,239,.55)}
.notmoved{margin-top:48px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
.notmoved div{border:1px solid var(--line-dark);border-radius:var(--r);padding:22px;font-size:15px;color:rgba(248,246,239,.84)}
.notmoved h3{font-size:17px;color:var(--rice);margin-bottom:6px}

/* roadmap */
.road{display:grid;grid-template-columns:repeat(9,minmax(0,1fr));margin-top:56px;position:relative}
.road::before{content:"";position:absolute;left:0;right:0;top:11px;height:3px;background:linear-gradient(90deg,var(--leaf) 0 74%,var(--line) 74% 100%)}
.rs{position:relative;padding-top:36px;padding-right:12px;font-size:14px;line-height:1.35}
.rs::before{content:"";position:absolute;left:0;top:3px;width:19px;height:19px;border-radius:50%;background:var(--leaf)}
.rs.here::before{background:var(--yellow);box-shadow:0 0 0 6px rgba(255,210,71,.35)}
.rs.here b{color:var(--chilli)}
.rs.next{color:var(--mute)} .rs.next::before{background:var(--rice);border:3px solid var(--line)}
.rs b{display:block;font-weight:700;font-size:15px;margin-bottom:2px}

/* reflection & footer */
.refl{font-size:clamp(26px,2.8vw,38px);line-height:1.25;letter-spacing:-.015em;max-width:30ch;font-variation-settings:"opsz" 48}
.refl b{font-weight:700} .refl .lt{font-weight:300;color:var(--mute)}
footer{padding:96px 0 64px;border-top:1px solid var(--line)}
footer .lock{width:220px}
.credits{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:40px;margin-top:40px;font-size:15px}
.credits h3{font-size:14px;color:var(--mute);font-weight:500;margin-bottom:10px}
.credits li{list-style:none;margin-bottom:6px}
.credits li b{font-weight:600}
.me{font-size:22px;font-weight:700}

/* motion */
.rv{transition:opacity .9s var(--ease),filter .9s var(--ease),transform .9s var(--ease)}
.js .rv:not(.in){opacity:0;filter:blur(10px);transform:translateY(14px)}
@media (prefers-reduced-motion:reduce){
  .js .rv:not(.in){opacity:1;filter:none;transform:none}
  .js .sun{transform:none;opacity:1}
  .js .tl .fill{transform:none}
  .live{height:auto!important}.live .sticky{position:relative;height:auto}
  .cf-card{transform:none!important}
}
@media print{.js .rv:not(.in){opacity:1;filter:none;transform:none}.js .zcaps .zcap{display:block}}

/* responsive */
@media (max-width:1000px){
  :root{--pad:28px}
  .row{grid-template-columns:1fr;gap:14px}
  .lab{padding-top:0}
  .glance,.defs,.limits{grid-template-columns:1fr}
  .steps4{grid-template-columns:1fr 1fr}
  .opts{grid-template-columns:1fr 1fr}
  .routes{grid-template-columns:1fr 1fr}
  .pair{grid-template-columns:1fr}
  .pair .m{max-width:320px}
  .wa{grid-template-columns:1fr 1fr}
  .wa .stack{grid-column:1/-1;grid-template-columns:1fr 1fr}
  .palette{grid-template-columns:1fr 1fr}
  .stats{grid-template-columns:1fr 1fr}
  .notmoved{grid-template-columns:1fr}
  .road{grid-template-columns:1fr;gap:4px}
  .road::before{left:8px;right:auto;top:0;bottom:0;width:3px;height:auto;background:linear-gradient(180deg,var(--leaf) 0 74%,var(--line) 74% 100%)}
  .rs{padding:0 0 18px 40px}.rs::before{top:0}
  .credits{grid-template-columns:1fr}
  .ev{grid-template-columns:1fr;gap:18px}
  .ev .media{max-width:300px}
  .withheld{grid-template-columns:1fr}
  .branch{display:none}
  .lane{grid-template-columns:1fr;gap:8px}
  .lane.mk .seg{font-size:11px}
  section{padding:96px 0}.dec{padding:88px 0}
}
@media (max-width:560px){
  .hero .top{align-items:flex-start}.chip:not(.live){display:none}
  .hero-in{padding-top:48px}
  .steps4,.opts,.routes,.trio,.palette,.stats{grid-template-columns:1fr}
  .wa,.wa .stack{grid-template-columns:1fr}
  .kv{grid-template-columns:1fr;gap:4px}
  .ruler .tick span{font-size:11px}
  .lane.mk .bar{height:auto;flex-direction:column}
  .lane.mk .seg{border-right:0;border-bottom:1px solid rgba(248,246,239,.18);padding:8px}
}

