(function(){
  var d=document.documentElement; d.classList.add('js');
  var rm=window.matchMedia('(prefers-reduced-motion: reduce)').matches; if(rm) d.classList.add('rm');
  var scene=document.querySelector('.scene'); var sio=new IntersectionObserver(function(es){ if(es[0].isIntersecting){ setTimeout(function(){d.classList.add('ready')},60); sio.disconnect(); } },{threshold:.35}); sio.observe(scene);

  // progressive blur reveal, once
  var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}})},{threshold:.25});
  document.querySelectorAll('.rv').forEach(function(el){io.observe(el)});

  // count up, once, only for sourced numbers
  var cio=new IntersectionObserver(function(es){es.forEach(function(e){
    if(!e.isIntersecting) return; cio.unobserve(e.target);
    var el=e.target,n=+el.dataset.n,suf=el.dataset.suf||'',t0=null;
    if(rm){return;}
    function step(t){ if(!t0)t0=t; var p=Math.min(1,(t-t0)/1100), v=Math.round(n*(1-Math.pow(1-p,3))); el.textContent=v+suf; if(p<1)requestAnimationFrame(step); }
    requestAnimationFrame(step);
  })},{threshold:.6});
  document.querySelectorAll('.stat .v').forEach(function(el){cio.observe(el)});

  // zone ruler
  var ticks=[].slice.call(document.querySelectorAll('.tick')), caps=[].slice.call(document.querySelectorAll('.zcap'));
  function setZ(i){ ticks.forEach(function(t,k){t.classList.toggle('on',k===i);t.setAttribute('aria-selected',k===i)}); caps.forEach(function(c,k){c.classList.toggle('on',k===i)}); }
  ticks.forEach(function(t,i){ t.addEventListener('click',function(){setZ(i)}); t.addEventListener('keydown',function(ev){ if(ev.key==='ArrowRight'){setZ(Math.min(ticks.length-1,i+1));ticks[Math.min(ticks.length-1,i+1)].focus()} if(ev.key==='ArrowLeft'){setZ(Math.max(0,i-1));ticks[Math.max(0,i-1)].focus()} }); });

  // coverflow
  var cf=document.getElementById('cf'), cards=[].slice.call(cf.querySelectorAll('.cf-card'));
  function flow(){ if(rm) return; var c=cf.getBoundingClientRect(), mid=c.left+c.width/2;
    cards.forEach(function(el){ var r=el.getBoundingClientRect(), off=(r.left+r.width/2-mid)/r.width; off=Math.max(-2.2,Math.min(2.2,off));
      el.style.transform='rotateY('+(-off*22)+'deg) scale('+(1-Math.abs(off)*0.08)+') translateZ('+(-Math.abs(off)*40)+'px)'; el.style.opacity=(1-Math.abs(off)*0.18); }); }
  cf.addEventListener('scroll',function(){requestAnimationFrame(flow)},{passive:true});
  window.addEventListener('resize',flow); setTimeout(function(){ cf.scrollLeft=(cf.scrollWidth-cf.clientWidth)/2; flow(); },300);
  function nudge(dir){ cf.scrollBy({left:dir*328,behavior:rm?'auto':'smooth'}); }
  document.getElementById('cfp').onclick=function(){nudge(-1)}; document.getElementById('cfn').onclick=function(){nudge(1)};
  var down=false,sx=0,sl=0; cf.addEventListener('pointerdown',function(e){ if(e.pointerType!=='mouse')return; down=true;sx=e.clientX;sl=cf.scrollLeft;cf.style.scrollSnapType='none'; });
  window.addEventListener('pointerup',function(){ if(down){down=false;cf.style.scrollSnapType='';} });
  window.addEventListener('pointermove',function(e){ if(down){cf.scrollLeft=sl-(e.clientX-sx);} });

  // timeline fill + live store scrub
  var tl=document.getElementById('tl'), fill=document.getElementById('tlfill'), evs=[].slice.call(tl.querySelectorAll('.ev'));
  var live=document.getElementById('live'), vp=document.getElementById('vp'), img=document.getElementById('liveimg'), prog=document.getElementById('prog');
  function onScroll(){
    var vh=window.innerHeight;
    if(!rm){ var r=tl.getBoundingClientRect(), p=Math.max(0,Math.min(1,(vh*0.6-r.top)/r.height)); fill.style.transform='scaleY('+p+')'; }
    evs.forEach(function(e){ e.classList.toggle('on', e.getBoundingClientRect().top<vh*0.6); });
    if(!rm){ var lr=live.getBoundingClientRect(), span=lr.height-vh; var q=Math.max(0,Math.min(1,(-lr.top+vh*0.15)/span));
      var max=Math.max(0,img.offsetHeight-vp.clientHeight); img.style.transform='translateY('+(-q*max)+'px)'; prog.style.transform='scaleX('+q+')'; }
  }
  if(rm){ live.style.height='auto'; }
  window.addEventListener('scroll',function(){requestAnimationFrame(onScroll)},{passive:true});
  window.addEventListener('resize',onScroll); img.addEventListener('load',onScroll); onScroll();

  // hook words brighten as the hero leaves (reading guide), final state is the mixed weight statement
})();

temple.styles:
:root{
  --night:#212522; --room:#262B27; --side:#4C564E; --lime:#E6F493; --limedeep:#8FA11E;
  --paper:#F2EFE7; --sheet:#FFFFFF; --ink:#1E211E; --mute:#62665F; --line:#DCD8CC;
  --linedark:rgba(242,239,231,.14); --mutedark:rgba(242,239,231,.62);
  --cut:#D8402F; --r:22px; --maxw:1280px; --pad:48px; --spine:210px;
  --ease:cubic-bezier(.22,.61,.36,1);
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{background:var(--paper);color:var(--ink);font-family:"Urbanist",system-ui,sans-serif;font-size:19px;line-height:1.6;-webkit-font-smoothing:antialiased}
img{display:block;max-width:100%;height:auto}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 var(--pad)}
.dot{font-family:"Doto",monospace}
section{padding:136px 0}
.dark{background:var(--night);color:var(--paper)}

/* spine */
.row{display:grid;grid-template-columns:var(--spine) minmax(0,1fr);gap:56px;align-items:start}
.lab{font-size:15px;font-weight:600;color:var(--mute);padding-top:16px;display:flex;gap:10px;align-items:center;line-height:1.3}
.lab::before{content:"";width:9px;height:9px;border-radius:50%;background:var(--limedeep);flex:none}
.dark .lab{color:var(--mutedark)} .dark .lab::before{background:var(--lime)}
h2{font-size:clamp(32px,4.2vw,56px);line-height:1.06;font-weight:700;letter-spacing:-.02em;max-width:21ch}
h2 .lt{font-weight:300;color:var(--mute)} .dark h2 .lt{color:var(--mutedark)}
h3{font-size:clamp(26px,2.6vw,36px);line-height:1.12;font-weight:700;letter-spacing:-.015em;max-width:24ch}
.body{max-width:64ch;margin-top:28px}
.body p+p{margin-top:16px}
.dark .body{color:rgba(242,239,231,.86)}
.mute{color:var(--mute)} .dark .mute{color:var(--mutedark)}
.small{font-size:15px;line-height:1.5}

/* figures */
figure{margin-top:56px}
.frame{border-radius:var(--r);overflow:hidden;background:var(--night);box-shadow:0 1px 0 rgba(0,0,0,.04),0 30px 60px -30px rgba(33,37,34,.45);border:1px solid rgba(0,0,0,.08)}
.dark .frame{border:1px solid var(--linedark);box-shadow:none}
figcaption{font-size:15px;line-height:1.5;color:var(--mute);margin-top:16px;max-width:80ch;display:flex;gap:10px}
.dark figcaption{color:var(--mutedark)}
.sample{display:inline-block;flex:none;font-size:12px;font-weight:700;letter-spacing:.02em;padding:2px 9px;border-radius:99px;background:var(--ink);color:var(--lime);height:fit-content;margin-top:2px}
.dark .sample{background:var(--lime);color:var(--night)}

/* hero */
.hero{padding:40px 0 0;position:relative;overflow:hidden}
.hero::before{content:"";position:absolute;inset:0;background-image:radial-gradient(rgba(230,244,147,.13) 1.2px,transparent 1.3px);background-size:22px 22px;mask-image:linear-gradient(#000,transparent 70%);-webkit-mask-image:linear-gradient(#000,transparent 70%);pointer-events:none}
.top{display:flex;justify-content:space-between;align-items:center;font-size:15px;color:var(--mutedark);position:relative}
.top b{color:var(--paper);font-weight:600}
.title{position:relative;margin-top:120px;display:flex;align-items:flex-end;gap:32px;flex-wrap:wrap}
h1{font-size:clamp(88px,15vw,212px);line-height:.82;font-weight:800;letter-spacing:-.045em}
.tag{font-style:italic;color:var(--mutedark);font-size:clamp(20px,2vw,28px);padding-bottom:12px}
.oneline{position:relative;margin-top:40px;font-size:clamp(20px,1.8vw,24px);color:var(--mutedark);max-width:48ch}
.hook{position:relative;margin-top:88px;font-size:clamp(28px,3.4vw,46px);line-height:1.22;font-weight:300;color:rgba(242,239,231,.5);max-width:30ch;letter-spacing:-.01em}
.hook b{font-weight:700;color:var(--paper)}
.herofig{position:relative;margin-top:88px;padding-bottom:0}
.herofig .frame{border-bottom-left-radius:0;border-bottom-right-radius:0;border-bottom:0}

/* glance */
.glance{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--ink)}
.glance div{padding:22px 0 24px;border-bottom:1px solid var(--line);display:grid;grid-template-columns:150px 1fr;gap:20px}
.glance div:nth-child(odd){padding-right:40px}
.glance div:nth-child(even){padding-left:40px;border-left:1px solid var(--line)}
.glance dt{font-size:15px;font-weight:600;color:var(--mute);padding-top:2px}
.glance dd{font-size:17px;line-height:1.5}
.glance dd b{font-weight:700}
.rooms{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:40px}
.room{border:1px solid var(--line);border-radius:18px;padding:22px 24px;background:rgba(255,255,255,.4)}
.room h4{font-size:20px;font-weight:700}
.room p{font-size:15px;line-height:1.5;color:var(--mute);margin-top:6px}
.room.on{background:var(--night);color:var(--paper);border-color:var(--night)}
.room.on p{color:var(--mutedark)}
.room .flag{display:inline-block;margin-top:14px;font-size:13px;font-weight:700;color:var(--night);background:var(--lime);padding:3px 10px;border-radius:99px}

/* before and after */
.week{margin-top:56px;border-top:1px solid var(--ink)}
.week .h,.week .r{display:grid;grid-template-columns:1.1fr 1fr;gap:40px;padding:18px 0;border-bottom:1px solid var(--line)}
.week .h{font-size:14px;font-weight:700;color:var(--mute)}
.week .r div:first-child{color:var(--mute);text-decoration:line-through;text-decoration-color:rgba(216,64,47,.55);text-decoration-thickness:1.5px}
.week .r div:last-child{font-weight:600}
.week .r div:last-child::before{content:"→";color:var(--limedeep);margin-right:10px;font-weight:700}

/* jtbd */
.jobs{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:48px}
.job{background:var(--sheet);border-radius:18px;padding:26px 28px;border:1px solid var(--line);font-size:18px;line-height:1.5}
.job span{display:block;color:var(--mute);font-weight:400}
.job b{font-weight:700}

/* turn */
.turn{padding:150px 0 130px}
.turnq{font-size:clamp(34px,4.4vw,64px);line-height:1.12;font-weight:300;letter-spacing:-.02em;color:rgba(242,239,231,.5);max-width:24ch}
.turnq b{font-weight:700;color:var(--paper)}
.turnq b.l{color:var(--lime)}
.outputs{display:grid;grid-template-columns:1.25fr 1fr;gap:40px;margin-top:80px;align-items:stretch}
.out{background:var(--room);border:1px solid var(--linedark);border-radius:var(--r);padding:28px}
.out h4{font-size:15px;font-weight:600;color:var(--mutedark);margin-bottom:14px}
.out svg{width:100%;height:auto;display:block}
.route path.road{fill:none;stroke:rgba(242,239,231,.14);stroke-width:3}
.route path.drive{fill:none;stroke:var(--lime);stroke-width:3;stroke-linecap:round}
.route circle{fill:var(--room);stroke:rgba(242,239,231,.35);stroke-width:2;transition:fill .3s,stroke .3s}
.route circle.hit{fill:var(--lime);stroke:var(--lime)}
.route text{fill:rgba(242,239,231,.75);font:500 13px Urbanist,sans-serif}
.bubble{opacity:0;transform:translateY(10px);transition:opacity .5s var(--ease),transform .5s var(--ease)}
.bubble.show{opacity:1;transform:none}
.a4 .slip{opacity:0;transform:translateY(-14px);transition:opacity .45s var(--ease),transform .45s var(--ease)}
.a4.show .slip{opacity:1;transform:none}
.a4 .cutl{stroke:var(--cut);stroke-width:1.6;stroke-dasharray:6 5;fill:none}
.a4 .guide{stroke-dashoffset:0}
.stat{display:flex;gap:28px;margin-top:18px;flex-wrap:wrap}
.stat div{font-size:14px;color:var(--mutedark);line-height:1.35}
.stat b{display:block;font-family:"Doto",monospace;font-size:34px;font-weight:800;color:var(--lime);line-height:1}

/* branches */
.tree{margin-top:64px}
.pcard{max-width:560px;margin:0 auto;background:var(--night);color:var(--paper);border-radius:18px;padding:22px 28px;text-align:center;font-size:20px;font-weight:600;line-height:1.4}
.pcard span{display:block;font-size:14px;color:var(--mutedark);font-weight:500;margin-bottom:6px}
.stem{height:40px;width:1px;background:var(--ink);margin:0 auto}
.bar{height:1px;background:var(--ink);margin:0 12.5%}
.opts{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.opt{position:relative;background:var(--sheet);border:1px solid var(--line);border-radius:18px;padding:22px 22px 24px;margin-top:32px;font-size:16px;line-height:1.5}
.opt::before{content:"";position:absolute;top:-33px;left:50%;width:1px;height:32px;background:var(--ink)}
.opt h4{font-size:19px;font-weight:700;margin:10px 0 8px;line-height:1.25}
.verdict{display:inline-block;font-size:12px;font-weight:700;padding:3px 10px;border-radius:99px;border:1px solid var(--line);color:var(--mute)}
.verdict.kill{color:var(--cut);border-color:rgba(216,64,47,.35)}
.verdict.keep{color:var(--ink);border-color:var(--ink)}
.opt.win{background:var(--night);color:var(--paper);border-color:var(--night)}
.opt.win .verdict{background:var(--lime);color:var(--night);border-color:var(--lime)}
.opt.win p{color:rgba(242,239,231,.8)}
.chips{display:flex;flex-wrap:wrap;gap:10px;margin-top:40px}
.chips span{font-size:14px;font-weight:600;padding:7px 14px;border-radius:99px;border:1px solid var(--ink)}
.rev{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:28px}
.rv3{border-top:2px solid var(--cut);padding-top:18px;font-size:16px;line-height:1.55}
.rv3 h4{font-size:19px;font-weight:700;line-height:1.25;margin-bottom:8px}
.subhead{font-size:22px;font-weight:700;margin-top:72px}

/* decisions */
.dec{padding:120px 0 0}
.dec:last-of-type{padding-bottom:136px}
.num{font-family:"Doto",monospace;font-weight:800;font-size:84px;line-height:.8;color:var(--limedeep);opacity:.55;margin-bottom:22px;display:block}
.pair{display:grid;grid-template-columns:1.45fr 1fr;gap:24px;align-items:start}

/* craft */
.pal{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:56px}
.sw{border-radius:16px;overflow:hidden;border:1px solid var(--linedark)}
.sw .c{height:104px;padding:14px;font-size:13px;font-weight:600}
.sw .m{padding:14px 16px;font-size:14px;line-height:1.45;background:var(--room)}
.sw .m b{display:block;font-size:16px}
.sw .m span{color:var(--mutedark)}
.pass{display:inline-block;margin-top:6px;font-size:12px;font-weight:700;padding:2px 8px;border-radius:99px;background:rgba(230,244,147,.14);color:var(--lime)}
.pass.no{background:rgba(216,64,47,.2);color:#FF8C7D}
.type{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:64px;border-top:1px solid var(--linedark);padding-top:40px}
.spec{font-size:13px;color:var(--mutedark);margin-top:10px;font-weight:500}
.bug{margin-top:72px;display:grid;grid-template-columns:1fr 1.2fr;gap:48px;align-items:center;border-top:1px solid var(--linedark);padding-top:48px}
.ruler{position:relative;height:120px}
.ruler .axis{position:absolute;left:0;right:0;top:64px;height:1px;background:rgba(242,239,231,.4)}
.ruler .mk{position:absolute;top:44px;width:1px;height:40px;background:rgba(242,239,231,.4)}
.ruler .mk span{position:absolute;top:46px;left:50%;transform:translateX(-50%);font-size:13px;color:var(--mutedark);white-space:nowrap}
.ruler .dev{position:absolute;top:52px;height:24px;background:rgba(230,244,147,.25);border:1px solid var(--lime);border-radius:6px}
.ruler .old{position:absolute;top:10px;width:2px;height:108px;background:var(--cut)}
.ruler .new{position:absolute;top:10px;width:2px;height:108px;background:var(--lime)}
.ruler .old b,.ruler .new b{position:absolute;top:-4px;left:8px;font-size:13px;white-space:nowrap}
.ruler .old b{color:#FF8C7D}.ruler .new b{color:var(--lime)}

/* outcome */
.retired{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-top:48px}
.retired div{background:var(--sheet);border:1px solid var(--line);border-radius:16px;padding:18px;font-size:16px;font-weight:600;line-height:1.35}
.retired div span{display:block;font-size:13px;font-weight:600;color:var(--cut);margin-bottom:8px}
.still{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:12px}
.still div{border:1px dashed var(--mute);border-radius:16px;padding:18px;font-size:15px;line-height:1.45;color:var(--mute)}
.still div b{display:block;color:var(--ink);font-size:16px;margin-bottom:4px}
.metric{display:inline;background:#FFF1A8;border:1px dashed #B59A00;padding:1px 8px;border-radius:6px;font-size:.9em;font-weight:600}
.flaws{margin-top:56px;background:var(--sheet);border-radius:var(--r);padding:32px 36px;border-left:4px solid var(--cut)}
.flaws h4{font-size:20px;font-weight:700}
.flaws p{margin-top:10px;font-size:17px;max-width:70ch}

/* roadmap */
.road{margin-top:64px;display:grid;grid-template-columns:repeat(6,1fr);position:relative}
.road::before{content:"";position:absolute;left:0;right:0;top:9px;height:2px;background:var(--line)}
.road .st{position:relative;padding-top:34px;padding-right:18px;font-size:15px;line-height:1.4}
.road .st::before{content:"";position:absolute;top:2px;left:0;width:16px;height:16px;border-radius:50%;background:var(--ink)}
.road .st.f{color:var(--mute)} .road .st.f::before{background:var(--paper);border:2px solid var(--line)}
.road .st b{display:block;font-size:13px;color:var(--mute);font-weight:600;margin-bottom:4px}
.road .here{position:absolute;top:-30px;left:0;font-size:12px;font-weight:700;background:var(--lime);color:var(--night);padding:2px 9px;border-radius:99px;white-space:nowrap}

footer{padding:96px 0 80px;font-size:15px;line-height:1.6}
.cred{display:grid;grid-template-columns:repeat(4,1fr);gap:32px;border-top:1px solid var(--linedark);padding-top:32px}
.cred b{display:block;color:var(--paper);font-weight:700;margin-bottom:6px}
.cred div{color:var(--mutedark)}

/* reveal */
.rv{opacity:0;transform:translateY(22px);filter:blur(6px);transition:opacity .8s var(--ease),transform .8s var(--ease),filter .8s var(--ease)}
.rv.in{opacity:1;transform:none;filter:none}
@media (prefers-reduced-motion:reduce){
  .rv{opacity:1;transform:none;filter:none;transition:none}
  html{scroll-behavior:auto}
  .bubble,.a4 .slip{opacity:1;transform:none;transition:none}
}
@media (max-width:980px){
  :root{--pad:24px}
  section{padding:96px 0}
  .row{grid-template-columns:1fr;gap:14px}
  .lab{padding-top:0}
  .glance{grid-template-columns:1fr}
  .glance div:nth-child(even){padding-left:0;border-left:0}
  .glance div:nth-child(odd){padding-right:0}
  .glance div{grid-template-columns:120px 1fr}
  .rooms,.jobs,.outputs,.pair,.type,.bug,.rev,.still{grid-template-columns:1fr}
  .opts{grid-template-columns:1fr 1fr}
  .opt::before,.bar{display:none}
  .pal{grid-template-columns:1fr 1fr}
  .retired{grid-template-columns:1fr 1fr}
  .road{grid-template-columns:1fr 1fr;row-gap:28px}
  .road::before{display:none}
  .cred{grid-template-columns:1fr 1fr}
  .week .h,.week .r{grid-template-columns:1fr;gap:6px}
  .week .h div:last-child{display:none}
  .title{margin-top:72px}
}

