(function(){
  var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}})},{threshold:.12});
  document.querySelectorAll('.rv').forEach(function(el){ if(reduce){el.classList.add('in')} else io.observe(el); });

  var drive=document.getElementById('drive'), route=document.getElementById('route');
  var stops=[].slice.call(document.querySelectorAll('#stops circle'));
  var bubble=document.getElementById('bubble');
  var len=drive.getTotalLength();
  var marks=stops.map(function(c){
    var best=0,bd=1e9,cx=+c.getAttribute('cx'),cy=+c.getAttribute('cy');
    for(var i=0;i<=200;i++){var p=drive.getPointAtLength(len*i/200),d=(p.x-cx)*(p.x-cx)+(p.y-cy)*(p.y-cy);if(d<bd){bd=d;best=i/200}}
    return best;
  });
  function setRoute(t){
    drive.style.strokeDasharray=len; drive.style.strokeDashoffset=len*(1-t);
    stops.forEach(function(c,i){c.classList.toggle('hit',t>=marks[i]-0.01)});
    bubble.classList.toggle('show',t>0.97);
  }
  var a4=document.getElementById('a4'), guides=[document.getElementById('cutv'),document.getElementById('cuth')];
  function setGuides(t){guides.forEach(function(g){var L=g.getTotalLength();g.style.strokeDasharray='6 5';g.style.clipPath='inset(0 '+(100-t*100)+'% '+(100-t*100)+'% 0)'})}
  if(reduce){setRoute(1);a4.classList.add('show');setGuides(1);return;}
  setRoute(0); setGuides(0);
  var ticking=false;
  function onScroll(){
    if(ticking)return; ticking=true;
    requestAnimationFrame(function(){
      var r=route.getBoundingClientRect(), vh=window.innerHeight;
      var t=Math.min(1,Math.max(0,(vh*0.9-r.top)/(vh*0.6)));
      setRoute(t);
      var q=a4.getBoundingClientRect();
      if(q.top<vh*0.75) a4.classList.add('show');
      var g=Math.min(1,Math.max(0,(vh*0.7-q.top)/(vh*0.4)));
      setGuides(g);
      ticking=false;
    });
  }
  window.addEventListener('scroll',onScroll,{passive:true}); onScroll();
})();

the-local-project.styles:
:root{
  --bg:#FFFFFF; --soft:#F5F3EF; --ink:#1B1A18; --muted:#77736B; --line:#E7E4DE; --stone:#B7AC9A;
  --serif:"Bodoni Moda","Didot","Bodoni 72",Georgia,serif;
  --sans:"Instrument Sans","Helvetica Neue",Helvetica,Arial,sans-serif;
  --ease:cubic-bezier(.22,1,.36,1);
  --pad:clamp(20px,3.6vw,56px);
  box-sizing:border-box;
  padding-top:env(safe-area-inset-top,0px);
  padding-bottom:env(safe-area-inset-bottom,0px);
}
:root[data-theme="dark"]{--bg:#FFFFFF;--soft:#F5F3EF;--ink:#1B1A18;--muted:#77736B;--line:#E7E4DE}
*,*::before,*::after{box-sizing:inherit}
html{scroll-padding-top:env(safe-area-inset-top,0px);-webkit-text-size-adjust:100%}
html.lenis,html.lenis body{height:auto}
.lenis.lenis-smooth{scroll-behavior:auto!important}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:16px;line-height:1.6;overflow-x:hidden}
svg{display:block;max-width:100%}
a{color:inherit;text-decoration:none}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
:focus-visible{outline:1.5px solid var(--ink);outline-offset:4px}
.wrap{padding:0 var(--pad)}
.line{display:block;overflow:hidden;padding-bottom:.08em;margin-bottom:-.08em}
.line-inner{display:inline-block;will-change:transform}
.serif{font-family:var(--serif);font-weight:400;letter-spacing:-.01em}

/* image frames with film grain */
.img{position:relative;overflow:hidden;background:var(--soft)}
.img .pic{position:absolute;inset:-8% 0;will-change:transform}
.img svg,.img img{width:100%;height:100%;display:block;object-fit:cover}
.img::after{content:"";position:absolute;inset:0;pointer-events:none;opacity:.08;mix-blend-mode:multiply;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 .5  0 0 0 0 .45  0 0 0 0 .4  0 0 0 .55 0'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>")}

/* ---------- loader ---------- */
.loader{position:fixed;inset:0;z-index:100;background:var(--bg);display:grid;place-items:center}
.loader-word{font-family:var(--serif);font-size:clamp(28px,4vw,54px);display:flex;gap:.28em;overflow:hidden}
.loader-word span{display:inline-block}
.loader-bar{position:absolute;left:var(--pad);right:var(--pad);bottom:calc(var(--pad) + env(safe-area-inset-bottom,0px));height:1px;background:var(--line)}
.loader-bar i{position:absolute;inset:0;background:var(--ink);transform-origin:0 50%;transform:scaleX(0)}
.loader-pct{position:absolute;right:var(--pad);bottom:calc(var(--pad) + 14px + env(safe-area-inset-bottom,0px));font-size:13px;color:var(--muted);font-variant-numeric:tabular-nums}

/* ---------- nav ---------- */
.nav{position:fixed;top:0;left:0;right:0;z-index:50;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:calc(20px + env(safe-area-inset-top,0px)) var(--pad) 20px;color:#fff;transition:color .5s var(--ease),background .5s var(--ease)}
.nav.solid{color:var(--ink);background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}
.nav-links{display:flex;gap:28px;font-size:14px}
.nav-links a{position:relative;padding:12px 0}
.nav-links a::after{content:"";position:absolute;left:0;right:0;bottom:8px;height:1px;background:currentColor;transform:scaleX(0);transform-origin:100% 50%;transition:transform .6s var(--ease)}
.nav-links a:hover::after{transform:scaleX(1);transform-origin:0 50%}
.logo{font-family:var(--serif);font-size:22px;white-space:nowrap}
.logo em{font-style:italic}
.nav-cta{justify-self:end;display:flex;align-items:center;gap:18px;font-size:14px}
.pill{border:1px solid currentColor;border-radius:999px;padding:11px 20px;min-height:44px;display:inline-flex;align-items:center;transition:background .4s var(--ease),color .4s var(--ease)}
.nav .pill:hover{background:currentColor}
.nav .pill:hover span{color:var(--bg)}
.nav.solid .pill:hover span{color:var(--bg)}
.nav:not(.solid) .pill:hover span{color:var(--ink)}
.menu-btn{display:none;min-height:44px;padding:0 4px}

.menu{position:fixed;inset:0;z-index:45;background:var(--bg);display:flex;flex-direction:column;justify-content:center;padding:var(--pad);clip-path:inset(0 0 100% 0);visibility:hidden}
.menu a{font-family:var(--serif);font-size:clamp(44px,11vw,84px);line-height:1.08;display:block;overflow:hidden}
.menu a span{display:inline-block}
.menu p{margin-top:40px;color:var(--muted)}

/* ---------- hero ---------- */
.hero{height:100svh;min-height:560px;position:relative;overflow:hidden;color:#fff}
.hero .img{position:absolute;inset:0}
.hero .img .pic{inset:0}
.hero-shade{position:absolute;inset:0;background:linear-gradient(to top,rgba(20,18,15,.62),rgba(20,18,15,0) 55%),linear-gradient(to bottom,rgba(20,18,15,.28),rgba(20,18,15,0) 24%)}
.hero-copy{position:absolute;left:var(--pad);right:var(--pad);bottom:calc(40px + env(safe-area-inset-bottom,0px));display:grid;grid-template-columns:1.6fr 1fr;gap:40px;align-items:end}
.hero h1{margin:0;font-size:clamp(46px,7.6vw,128px);line-height:.98}
.hero h1 em{font-style:italic}
.hero-side{font-size:15px;max-width:34ch;justify-self:end;color:rgba(255,255,255,.86)}
.scroll-cue{display:flex;align-items:center;gap:12px;margin-top:22px;font-size:13px;color:#fff}
.scroll-cue i{display:block;width:1px;height:38px;background:rgba(255,255,255,.35);position:relative;overflow:hidden}
.scroll-cue i::after{content:"";position:absolute;left:0;top:-40%;width:1px;height:40%;background:#fff;animation:cue 2s var(--ease) infinite}
@keyframes cue{to{top:100%}}

/* ---------- intro ---------- */
.intro{padding:clamp(120px,18vh,220px) var(--pad) clamp(90px,12vh,150px)}
.intro-grid{display:grid;grid-template-columns:1fr 3fr;gap:40px}
.label{font-size:13px;color:var(--muted)}
.intro p.big{font-family:var(--serif);font-size:clamp(28px,3.8vw,60px);line-height:1.14;margin:0;max-width:24ch}
.intro .w{opacity:.14}
.intro-cols{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:70px;max-width:760px;color:var(--muted)}
.intro-cols p{margin:0}

/* ---------- expanding banner ---------- */
.expand{height:100svh;overflow:hidden}
.expand .img{position:absolute;inset:0;clip-path:inset(20% 28% 20% 28%);will-change:clip-path}
.expand .img .pic{inset:-4% 0}
.expand-cap{position:absolute;left:var(--pad);right:var(--pad);bottom:40px;display:flex;justify-content:space-between;color:#fff;font-size:14px;opacity:0;z-index:2}

/* ---------- projects ---------- */
.projects{padding:clamp(110px,15vh,190px) 0 40px}
.sec-head{display:flex;justify-content:space-between;align-items:end;gap:30px;padding:0 var(--pad) clamp(50px,7vh,90px)}
.h2{margin:0;font-size:clamp(40px,5.6vw,92px);line-height:1}
.h2 em{font-style:italic}
.link-u{font-size:14px;border-bottom:1px solid var(--ink);padding-bottom:3px;white-space:nowrap}
.proj{display:grid;grid-template-columns:repeat(12,1fr);gap:0 var(--pad);padding:0 var(--pad);margin-bottom:clamp(90px,14vh,180px);align-items:end}
.proj .img{aspect-ratio:3/2}
.proj.a .img{grid-column:1 / 9}
.proj.a .meta{grid-column:9 / 13}
.proj.b .img{grid-column:5 / 13;grid-row:1}
.proj.b .meta{grid-column:1 / 5;grid-row:1}
.proj.c .img{grid-column:4 / 10;aspect-ratio:4/5}
.proj.c .meta{grid-column:4 / 10;grid-row:2;display:flex;justify-content:space-between;align-items:baseline;gap:20px;margin-top:22px}
.meta h3{font-family:var(--serif);font-weight:400;font-size:clamp(28px,2.8vw,44px);line-height:1.05;margin:0 0 12px}
.meta p{margin:0;color:var(--muted);max-width:32ch}
.facts{display:grid;grid-template-columns:auto 1fr;gap:6px 20px;margin-top:22px;font-size:14px}
.facts dt{color:var(--muted)}.facts dd{margin:0}
.proj .img .pic{transition:filter 1s var(--ease)}
.proj a.img:hover .pic>*{transform:scale(1.03)}
.proj .img .pic>*{transition:transform 1.4s var(--ease)}

/* ---------- practice ---------- */
.practice{background:var(--soft);padding:clamp(110px,15vh,190px) var(--pad)}
.practice-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(30px,6vw,110px)}
.practice-media{position:sticky;top:calc(12vh + env(safe-area-inset-top,0px));height:76vh}
.practice-media .img{position:absolute;inset:0;clip-path:inset(100% 0 0 0)}
.practice-media .img.on{clip-path:inset(0 0 0 0)}
.practice-media .img .pic{inset:0}
.disc{min-height:76vh;display:flex;flex-direction:column;justify-content:center;border-top:1px solid var(--line)}
.disc:first-child{border-top:0}
.disc h3{font-family:var(--serif);font-weight:400;font-size:clamp(40px,4.8vw,78px);line-height:1;margin:0 0 22px;color:var(--stone);transition:color .6s var(--ease)}
.disc.on h3{color:var(--ink)}
.disc p{margin:0;color:var(--muted);max-width:40ch;font-size:17px}
.disc ul{list-style:none;padding:0;margin:26px 0 0;display:flex;flex-wrap:wrap;gap:10px}
.disc li{border:1px solid var(--line);border-radius:999px;padding:6px 14px;font-size:13px;background:var(--bg)}

/* ---------- index ---------- */
.index{padding:clamp(110px,15vh,190px) var(--pad)}
.rows{list-style:none;margin:0;padding:0;border-top:1px solid var(--ink)}
.rows a{display:grid;grid-template-columns:3fr 2fr 1fr 1fr;gap:20px;align-items:baseline;padding:24px 0;border-bottom:1px solid var(--line);transition:color .4s var(--ease),padding .7s var(--ease)}
.rows strong{font-family:var(--serif);font-weight:400;font-size:clamp(22px,2.4vw,36px);line-height:1.1}
.rows span{color:var(--muted);font-size:14px}
.rows:hover a{color:var(--stone)}
.rows:hover a:hover{color:var(--ink);padding-left:16px}
.peek{position:fixed;left:0;top:0;width:300px;aspect-ratio:4/3;z-index:30;pointer-events:none;opacity:0;transform:translate(-50%,-50%) scale(.85)}
.peek .img{position:absolute;inset:0}
.peek .pic{inset:0}

/* ---------- journal ---------- */
.journal{padding:0 var(--pad) clamp(110px,15vh,190px)}
.posts{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--pad)}
.post .img{aspect-ratio:4/5}
.post h3{font-family:var(--serif);font-weight:400;font-size:clamp(22px,1.9vw,30px);line-height:1.15;margin:18px 0 8px}
.post span{color:var(--muted);font-size:14px}
.post .img .pic>*{transition:transform 1.4s var(--ease)}
.post:hover .img .pic>*{transform:scale(1.04)}

/* ---------- contact ---------- */
.contact{position:relative;min-height:100svh;color:#fff;overflow:hidden;display:flex;flex-direction:column;justify-content:flex-end;padding:0 var(--pad) calc(34px + env(safe-area-inset-bottom,0px))}
.contact>.img{position:absolute;inset:0}
.contact>.img .pic{inset:-10% 0}
.contact .hero-shade{background:linear-gradient(to top,rgba(20,18,15,.72),rgba(20,18,15,.1))}
.contact-inner{position:relative;z-index:2}
.contact h2{font-size:clamp(52px,9.4vw,168px);line-height:.94;margin:0}
.contact h2 em{font-style:italic}
.contact-row{display:flex;justify-content:space-between;align-items:end;gap:40px;flex-wrap:wrap;margin-top:50px}
.magnet{width:clamp(140px,13vw,184px);aspect-ratio:1;border-radius:50%;background:#fff;color:var(--ink);display:grid;place-items:center;font-size:15px;font-weight:500}
.magnet span{display:block}
.details{display:grid;grid-template-columns:repeat(3,auto);gap:10px 56px;font-size:14px}
.details b{display:block;font-weight:400;color:rgba(255,255,255,.62)}
.credits{position:relative;z-index:2;margin-top:14px;font-size:12px;color:rgba(255,255,255,.6)}
.credits a{text-decoration:underline;text-underline-offset:3px}
.fine{position:relative;z-index:2;display:flex;justify-content:space-between;flex-wrap:wrap;gap:14px;margin-top:70px;padding-top:22px;border-top:1px solid rgba(255,255,255,.25);font-size:13px;color:rgba(255,255,255,.72)}
.fine button{text-decoration:underline;text-underline-offset:4px;min-height:44px}

/* ---------- responsive ---------- */
@media (max-width:900px){
  .nav{grid-template-columns:1fr auto}
  .nav-links,.nav-cta .pill{display:none}
  .menu-btn{display:block}
  .hero-copy{grid-template-columns:1fr}
  .hero-side{justify-self:start}
  .intro-grid,.intro-cols,.practice-grid{grid-template-columns:1fr}
  .expand .img{clip-path:inset(24% 10% 24% 10%)}
  .proj{display:block}
  .proj .meta{margin-top:22px}
  .proj.c .meta{display:block}
  .practice-media{position:relative;top:0;height:56vh}
  .disc{min-height:auto;padding:40px 0}
  .disc h3{color:var(--ink)}
  .rows a{grid-template-columns:1fr auto}
  .rows a span:nth-of-type(2),.rows a span:nth-of-type(3){display:none}
  .posts{grid-template-columns:1fr}
  .details{grid-template-columns:1fr}
  .peek{display:none}
}
@media (prefers-reduced-motion:reduce){
  .scroll-cue i::after{animation:none}
  .intro .w{opacity:1}
  .practice-media .img{clip-path:none}
}

scripts.code:
(function(){
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const fine = matchMedia('(pointer: fine)').matches;
  const $ = (s, r=document) => r.querySelector(s);
  const $$ = (s, r=document) => [...r.querySelectorAll(s)];

  // paint scenes (gradient ids made unique per copy)
  const PHOTOS = {"dune": "media/the-local-project/dune.jpg", "brick": "media/the-local-project/brick.jpg", "drawing": "media/the-local-project/drawing.jpg", "curves": "media/the-local-project/curves.jpg", "brutal": "media/the-local-project/brutal.jpg", "interior": "media/the-local-project/interior.jpg", "lattice": "media/the-local-project/lattice.jpg"};
  const FOCUS = { dune:'55% 60%', brick:'55% 50%', drawing:'45% 50%', curves:'35% 50%', brutal:'70% 70%', interior:'62% 55%', lattice:'55% 45%' };
  const ALT = { dune:'Dark timber house on a grassy dune', brick:'Brick house with a landscaped garden', drawing:'Hand drawn measured plan with drafting tools', curves:'Curving white panelled terraces', brutal:'Board marked concrete building against a pale sky', interior:'Open living room with timber floors', lattice:'Terracotta facade with carved lattice screens' };
  let uid = 0;
  function scene(name){
    if (PHOTOS[name]){
      const img = new Image(); img.src = PHOTOS[name]; img.alt = ALT[name] || ''; img.decoding = 'async';
      img.style.objectPosition = FOCUS[name] || '50% 50%';
      return img;
    }
    return svgScene(name);
  }
  function svgScene(name){
    const t = document.getElementById('s-' + name); if (!t) return null;
    const n = t.content.cloneNode(true); const k = 'u' + (uid++);
    n.querySelectorAll('[id]').forEach(el => el.id = el.id + k);
    n.querySelectorAll('[fill^="url(#"]').forEach(el => el.setAttribute('fill', el.getAttribute('fill').replace(/\)$/, k + ')')));
    return n;
  }
  $$('.pic[data-scene]').forEach(p => { const s = scene(p.dataset.scene); s && p.appendChild(s); });

  // nav colour over images
  const nav = $('.nav');
  const setNav = () => {
    const y = window.scrollY, h = innerHeight;
    const contact = $('#contact').getBoundingClientRect();
    const overImage = y < h * .85 || (contact.top < 60 && contact.bottom > 60);
    nav.classList.toggle('solid', !overImage);
  };

  const loader = $('.loader');
  if (typeof gsap === 'undefined' || typeof ScrollTrigger === 'undefined'){ loader.remove(); addEventListener('scroll', setNav); setNav(); return; }
  gsap.registerPlugin(ScrollTrigger);

  let lenis = null;
  if (!reduce && typeof Lenis !== 'undefined'){
    lenis = new Lenis({ lerp: .085 });
    lenis.on('scroll', ScrollTrigger.update);
    gsap.ticker.add(t => lenis.raf(t * 1000));
    gsap.ticker.lagSmoothing(0);
  }
  const go = t => lenis ? lenis.scrollTo(t, { duration: 1.6 }) : (typeof t === 'number' ? scrollTo(0, t) : t.scrollIntoView());
  ScrollTrigger.create({ start: 0, end: 'max', onUpdate: setNav }); setNav();

  function splitLines(el){
    // keep <em> runs intact by splitting on text nodes into word spans
    const frag = [];
    el.childNodes.forEach(node => {
      const italic = node.nodeType === 1 && node.tagName === 'EM';
      node.textContent.trim().split(/\s+/).filter(Boolean).forEach(w => frag.push({ w, italic }));
    });
    el.innerHTML = frag.map(f => '<span class="wd" style="display:inline-block">' + (f.italic ? '<em>' + f.w + '</em>' : f.w) + '</span>').join(' ');
    const lines = []; let top = null;
    $$('.wd', el).forEach(w => { if (w.offsetTop !== top){ lines.push([]); top = w.offsetTop; } lines[lines.length - 1].push(w.innerHTML); });
    el.innerHTML = lines.map(l => '<span class="line"><span class="line-inner">' + l.join(' ') + '</span></span>').join('');
  }

  document.fonts.ready.then(init);

  function init(){
    $$('.split').forEach(splitLines);
    $$('.scrub').forEach(el => el.innerHTML = el.textContent.trim().split(/\s+/).map(w => '<span class="w">' + w + '</span>').join(' '));
    setupMenu();

    if (reduce){ loader.remove(); return; }

    // ---- intro: loader, then the hero image opens from a small frame ----
    const heroImg = $('.hero .img'), heroSvg = $('.hero .pic > *');
    gsap.set(heroImg, { clipPath: 'inset(38% 36% 38% 36%)' });
    gsap.set(heroSvg, { scale: 1.35 });
    gsap.set('.split-hero .line-inner', { yPercent: 110 });
    gsap.set(['.hero-side', '.nav'], { opacity: 0 });
    const pct = { v: 0 };
    const tl = gsap.timeline();
    tl.from('.loader-word span', { yPercent: 120, duration: 1, stagger: .1, ease: 'expo.out' })
      .to('.loader-bar i', { scaleX: 1, duration: 1.3, ease: 'power2.inOut' }, 0.2)
      .to(pct, { v: 100, duration: 1.3, ease: 'power2.inOut', onUpdate: () => $('.loader-pct').textContent = Math.round(pct.v) }, 0.2)
      .to('.loader-word span', { yPercent: -120, duration: .7, stagger: .05, ease: 'expo.in' })
      .to(loader, { opacity: 0, duration: .3 }, '-=.1')
      .to(heroImg, { clipPath: 'inset(0% 0% 0% 0%)', duration: 1.6, ease: 'expo.inOut' }, '-=.2')
      .to(heroSvg, { scale: 1, duration: 2.2, ease: 'expo.out' }, '<')
      .to('.split-hero .line-inner', { yPercent: 0, duration: 1.2, stagger: .12, ease: 'expo.out' }, '-=1')
      .to(['.hero-side', '.nav'], { opacity: 1, duration: 1, ease: 'power2.out' }, '-=.9')
      .add(() => loader.remove());
    if (lenis){ lenis.stop(); tl.add(() => lenis.start(), '-=1'); }

    // hero parallax out
    gsap.to('.hero .pic', { yPercent: 18, scale: 1.08, ease: 'none', scrollTrigger: { trigger: '.hero', start: 'top top', end: 'bottom top', scrub: true } });
    gsap.to('.hero-copy', { yPercent: -40, opacity: 0, ease: 'none', scrollTrigger: { trigger: '.hero', start: '40% top', end: 'bottom top', scrub: true } });

    // headings rise line by line
    $$('.split').forEach(el => gsap.from($$('.line-inner', el), { yPercent: 110, duration: 1.2, stagger: .1, ease: 'expo.out', scrollTrigger: { trigger: el, start: 'top 86%' } }));

    // intro words brighten with scroll
    gsap.to('.scrub .w', { opacity: 1, stagger: .1, ease: 'none', scrollTrigger: { trigger: '.intro', start: 'top 72%', end: 'center 45%', scrub: true } });
    gsap.from('.intro-cols p', { y: 30, opacity: 0, duration: 1.1, stagger: .12, ease: 'expo.out', scrollTrigger: { trigger: '.intro-cols', start: 'top 88%' } });

    // expanding banner: framed image grows to full bleed while pinned
    const ex = $('.expand .img');
    const exTl = gsap.timeline({ scrollTrigger: { trigger: '.expand', start: 'top top', end: '+=120%', pin: true, scrub: 1 } });
    exTl.to(ex, { clipPath: 'inset(0% 0% 0% 0%)', ease: 'power2.inOut' })
        .fromTo($('.pic', ex), { scale: 1.25 }, { scale: 1, ease: 'power2.inOut' }, 0)
        .to('.expand-cap', { opacity: 1, ease: 'none', duration: .25 }, .75);

    // image reveals: wipe up, settle from scale, then gentle parallax
    $$('.reveal').forEach(el => {
      const pic = $('.pic', el);
      gsap.fromTo(el, { clipPath: 'inset(100% 0 0 0)' }, { clipPath: 'inset(0% 0 0 0)', duration: 1.5, ease: 'expo.inOut', scrollTrigger: { trigger: el, start: 'top 85%' } });
      gsap.fromTo(pic, { scale: 1.3 }, { scale: 1, duration: 2, ease: 'expo.out', scrollTrigger: { trigger: el, start: 'top 85%' } });
      gsap.fromTo(pic, { yPercent: -5 }, { yPercent: 5, ease: 'none', scrollTrigger: { trigger: el, start: 'top bottom', end: 'bottom top', scrub: true } });
    });
    $$('.proj .meta').forEach(m => gsap.from(m.children, { y: 26, opacity: 0, duration: 1, stagger: .08, ease: 'expo.out', scrollTrigger: { trigger: m, start: 'top 88%' } }));

    // practice: image swaps as each discipline takes focus
    const mm = gsap.matchMedia();
    mm.add('(min-width: 901px)', () => {
      const imgs = $$('.practice-media .img'); const discs = $$('.disc'); let cur = 0; let z = 2;
      discs.forEach((d, i) => ScrollTrigger.create({ trigger: d, start: 'top 55%', end: 'bottom 55%',
        onToggle: s => { if (!s.isActive || i === cur) return;
          discs.forEach(x => x.classList.toggle('on', x === d));
          const im = imgs[i]; im.style.zIndex = ++z; cur = i;
          gsap.fromTo(im, { clipPath: 'inset(100% 0 0 0)' }, { clipPath: 'inset(0% 0 0 0)', duration: 1.2, ease: 'expo.inOut' });
          gsap.fromTo($('.pic > *', im), { scale: 1.2 }, { scale: 1, duration: 1.8, ease: 'expo.out' });
        } }));
    });

    // index rows stagger in, preview follows cursor
    gsap.from('.rows li', { y: 30, opacity: 0, duration: 1, stagger: .07, ease: 'expo.out', scrollTrigger: { trigger: '.rows', start: 'top 85%' } });
    if (fine){
      const peek = $('.peek'), ppic = $('.peek .pic');
      const xTo = gsap.quickTo(peek, 'x', { duration: .7, ease: 'power3' }), yTo = gsap.quickTo(peek, 'y', { duration: .7, ease: 'power3' });
      addEventListener('pointermove', e => { xTo(e.clientX); yTo(e.clientY); });
      $$('.rows a').forEach(a => {
        a.addEventListener('pointerenter', () => { ppic.innerHTML = ''; ppic.appendChild(scene(a.dataset.scene)); gsap.to(peek, { opacity: 1, scale: 1, duration: .6, ease: 'expo.out' }); });
        a.addEventListener('pointerleave', () => gsap.to(peek, { opacity: 0, scale: .85, duration: .4, ease: 'power2.out' }));
      });

      const m = $('.magnet'), s = $('span', m);
      const mx = gsap.quickTo(m, 'x', { duration: .5, ease: 'power3' }), my = gsap.quickTo(m, 'y', { duration: .5, ease: 'power3' });
      const sx = gsap.quickTo(s, 'x', { duration: .5, ease: 'power3' }), sy = gsap.quickTo(s, 'y', { duration: .5, ease: 'power3' });
      m.addEventListener('pointermove', e => { const r = m.getBoundingClientRect(); const dx = e.clientX - r.left - r.width / 2, dy = e.clientY - r.top - r.height / 2; mx(dx * .35); my(dy * .35); sx(dx * .15); sy(dy * .15); });
      m.addEventListener('pointerleave', () => gsap.to([m, s], { x: 0, y: 0, duration: 1.1, ease: 'elastic.out(1,.4)' }));
    }

    // contact banner parallax
    gsap.fromTo('.contact > .img .pic', { yPercent: -8 }, { yPercent: 8, ease: 'none', scrollTrigger: { trigger: '.contact', start: 'top bottom', end: 'bottom bottom', scrub: true } });
  }

  function setupMenu(){
    const btn = $('.menu-btn'), menu = $('.menu'); let open = false;
    const tl = gsap.timeline({ paused: true })
      .set(menu, { visibility: 'visible' })
      .to(menu, { clipPath: 'inset(0 0 0% 0)', duration: reduce ? 0 : .9, ease: 'expo.inOut' })
      .from('.menu a span', { yPercent: 110, duration: reduce ? 0 : .8, stagger: .06, ease: 'expo.out' }, '-=.4');
    const toggle = st => {
      open = st ?? !open; btn.setAttribute('aria-expanded', open); btn.textContent = open ? 'Close' : 'Menu';
      nav.style.color = open ? 'var(--ink)' : '';
      if (open){ tl.play(); lenis && lenis.stop(); } else { tl.reverse(); lenis && lenis.start(); }
    };
    btn.addEventListener('click', () => toggle());
    menu.addEventListener('keydown', e => { if (e.key === 'Escape') toggle(false); });
    $$('a[href^="#"]').forEach(a => a.addEventListener('click', e => {
      const id = a.getAttribute('href'); if (id.length < 2) return; const t = $(id); if (!t) return;
      e.preventDefault(); const wasOpen = open; if (open) toggle(false);
      setTimeout(() => go(id === '#top' ? 0 : t), wasOpen ? 400 : 0);
    }));
    $('.totop').addEventListener('click', () => go(0));
  }
})();

upgrad-design-system.styles:
:root{
  --neutral-white:#FFFFFF; --neutral-75:#F7F7F7; --neutral-100:#F2F2F2; --neutral-150:#EEEEEE;
  --neutral-200:#E8E8E8; --neutral-300:#D9D9D9; --neutral-400:#A5A5A5; --neutral-500:#717171;
  --neutral-600:#555555; --neutral-700:#393939; --neutral-800:#1D1D1D; --neutral-850:#171717;
  --neutral-black:#000000;
  --red-50:#FEEBED; --red-100:#FDCDD2; --red-200:#F8828D; --red-300:#EE2C3C; --red-400:#DC2132;
  --red-500:#C2192A; --red-600:#A31423; --red-700:#7F111C; --red-800:#540E14; --red-900:#2A0C0C;
  --green-400:#28AC52; --yellow-400:#F5C81C;

  --text-primary:var(--neutral-black); --text-secondary:var(--neutral-500);
  --text-tertiary:var(--neutral-400); --text-inverse:var(--neutral-white);
  --text-brand:var(--red-300);
  --surface-bg:var(--neutral-white); --surface-surface:var(--neutral-100);
  --surface-brand:var(--red-300);
  --border-primary:var(--neutral-150); --border-secondary:var(--neutral-200);

  --gutter:24px; --margin:120px; --maxw:1440px;
  --ease:cubic-bezier(.22,.61,.36,1);
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  background:var(--surface-bg); color:var(--text-primary);
  font-family:"DM Sans",system-ui,sans-serif; font-variation-settings:"opsz" 14;
  -webkit-font-smoothing:antialiased;
}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 var(--margin)}

/* ---------- type scale, taken from the system ---------- */
.h1{font-size:51px;line-height:100%;font-weight:500;letter-spacing:0}
.h2{font-size:48px;line-height:100%;font-weight:400;letter-spacing:0}
.h3{font-size:36px;line-height:120%;font-weight:500;letter-spacing:2px}
.h4{font-size:32px;line-height:120%;font-weight:600}
.h5{font-size:24px;line-height:120%;font-weight:600}
.accent{font-family:"Fraunces",Georgia,serif;font-style:italic;font-weight:600;letter-spacing:0}
.bodyL{font-size:18px;line-height:140%}
.body{font-size:16px;line-height:140%;letter-spacing:-.25px}
.bodyS{font-size:14px;line-height:140%}
.bodyXS{font-size:12px;line-height:140%;font-weight:600}
.dim{color:var(--text-secondary)}
.dimmer{color:var(--text-tertiary)}
.brand{color:var(--text-brand)}
strong{font-weight:600}

/* ---------- margin label spine ---------- */
.section{padding:120px 0;border-top:1px solid var(--border-primary)}
.spine{display:grid;grid-template-columns:200px 1fr;gap:var(--gutter)}
.label{
  font-size:12px;font-weight:600;letter-spacing:1.2px;text-transform:uppercase;
  color:var(--text-tertiary);display:flex;align-items:flex-start;gap:8px;padding-top:8px
}
.label::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--surface-brand);flex:0 0 8px;margin-top:5px}
.col{max-width:760px}
.col > * + *{margin-top:24px}

/* ---------- reveal ---------- */
.rv{opacity:0;transform:translateY(24px);transition:opacity .7s var(--ease),transform .7s var(--ease)}
.rv.in{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){.rv{opacity:1;transform:none;transition:none}html{scroll-behavior:auto}}

/* ---------- hero ---------- */
.hero{padding:96px 0 0}
.eyebrow{display:flex;gap:12px;align-items:center;font-size:12px;font-weight:600;letter-spacing:1.2px;text-transform:uppercase;color:var(--text-secondary)}
.pill{border:1px solid var(--border-secondary);border-radius:999px;padding:4px 12px;font-size:12px;font-weight:600;letter-spacing:.4px;text-transform:none;color:var(--text-secondary)}
.hookline{font-size:51px;line-height:110%;font-weight:400;color:var(--text-tertiary);max-width:15ch}
.hookline b{font-weight:600;color:var(--text-primary)}
.herofig{margin-top:64px;background:var(--surface-brand);border-radius:24px;padding:64px var(--margin);color:var(--text-inverse);overflow:hidden;position:relative}
.herofig .big{font-size:clamp(48px,9vw,128px);line-height:96%;font-weight:600;letter-spacing:-2px}

/* ---------- at a glance ---------- */
.glance{display:grid;grid-template-columns:repeat(4,1fr);gap:0;border-top:1px solid var(--border-primary);border-bottom:1px solid var(--border-primary)}
.gitem{padding:24px;border-right:1px solid var(--border-primary)}
.gitem:last-child{border-right:0}
.gitem dt{font-size:12px;font-weight:600;letter-spacing:1px;text-transform:uppercase;color:var(--text-tertiary);margin-bottom:8px}
.gitem dd{font-size:16px;line-height:140%}

/* ---------- token audit ---------- */
.audit{background:var(--neutral-75);border-radius:24px;padding:48px}
.dots{display:grid;grid-template-columns:repeat(23,1fr);gap:6px;margin:32px 0}
.dot{aspect-ratio:1;border-radius:50%;background:var(--neutral-300);transform:scale(.4);opacity:0;transition:transform .5s var(--ease),opacity .5s var(--ease),background .5s var(--ease)}
.dot.on{transform:scale(1);opacity:1}
.dot.kh{background:var(--red-300)}
.counts{display:flex;gap:48px;flex-wrap:wrap}
.count .n{font-size:48px;line-height:100%;font-weight:600;font-variant-numeric:tabular-nums}
.count .k{font-size:14px;color:var(--text-secondary);margin-top:4px}
.legend{display:flex;gap:20px;font-size:14px;color:var(--text-secondary);flex-wrap:wrap}
.legend i{display:inline-block;width:12px;height:12px;border-radius:50%;margin-right:8px;vertical-align:-1px}

/* ---------- turn ---------- */
.turn{background:var(--neutral-black);color:var(--text-inverse);border-radius:24px;padding:96px 64px;text-align:left}
.turn p{font-size:clamp(32px,5vw,64px);line-height:110%;font-weight:400;color:var(--neutral-400);max-width:18ch}
.turn p b{color:var(--neutral-white);font-weight:600}

/* ---------- toggle / tabs ---------- */
.switch{display:inline-flex;background:var(--neutral-100);border-radius:999px;padding:4px;gap:4px}
.switch button{
  font:inherit;font-size:14px;font-weight:500;border:0;cursor:pointer;background:transparent;
  color:var(--text-secondary);padding:8px 20px;border-radius:999px;transition:.25s var(--ease)
}
.switch button[aria-selected="true"]{background:var(--neutral-white);color:var(--text-primary);box-shadow:0 1px 3px rgba(0,0,0,.12)}
.panes{position:relative;margin-top:24px}
.pane{display:none}
.pane.on{display:block;animation:fade .4s var(--ease)}
@keyframes fade{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}

.codelist{background:var(--neutral-black);border-radius:16px;padding:32px;font-size:15px;line-height:2;color:var(--neutral-300)}
.codelist span{color:var(--red-200)}
.codelist em{font-style:normal;color:var(--neutral-500)}

/* ---------- typeface cards ---------- */
.faces{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--gutter)}
.face{border:1px solid var(--border-secondary);border-radius:16px;padding:28px;transition:.3s var(--ease);position:relative}
.face.killed{opacity:.55}
.face.chosen{border-color:var(--neutral-black);border-width:2px;padding:27px}
.face .name{font-size:32px;line-height:1;margin-bottom:20px}
.face .verdict{font-size:12px;font-weight:600;letter-spacing:1px;text-transform:uppercase;margin-bottom:12px}
.face.killed .verdict{color:var(--text-tertiary)}
.face.chosen .verdict{color:var(--text-brand)}
.face p{font-size:14px;line-height:150%;color:var(--text-secondary)}

/* ---------- token table ---------- */
.tbl{width:100%;border-collapse:collapse;font-size:15px}
.tbl th{text-align:left;font-size:12px;font-weight:600;letter-spacing:1px;text-transform:uppercase;color:var(--text-tertiary);padding:0 12px 14px}
.tbl td{padding:14px 12px;border-top:1px solid var(--border-primary);vertical-align:middle}
.sw{width:28px;height:28px;border-radius:50%;display:inline-block;border:1px solid rgba(0,0,0,.08)}
.hex{font-size:13px;border:1px solid var(--border-primary);border-radius:6px;padding:3px 9px;display:inline-block;color:var(--text-secondary)}
.alias{color:var(--text-secondary)}
.arrow{color:var(--text-tertiary);padding:0 6px}

/* ---------- button matrix ---------- */
.matrix{display:grid;grid-template-columns:120px repeat(3,1fr);gap:12px;align-items:center}
.matrix .hd{font-size:12px;font-weight:600;letter-spacing:1px;text-transform:uppercase;color:var(--text-tertiary)}
.btn{border:0;border-radius:8px;padding:12px 20px;font:inherit;font-size:15px;font-weight:500;cursor:default;width:100%}
.b-pri{background:var(--red-300);color:#fff}.b-pri.h{background:#BE2330}.b-pri.p{background:#8F1A24}
.b-sec{background:var(--neutral-200);color:var(--neutral-black)}.b-sec.h{background:var(--neutral-300)}.b-sec.p{background:var(--neutral-400)}
.b-acc{background:var(--neutral-black);color:#fff}.b-acc.h{background:var(--neutral-700)}.b-acc.p{background:var(--neutral-600)}
.live{margin-top:32px;padding:32px;background:var(--neutral-75);border-radius:16px;display:flex;gap:16px;align-items:center;flex-wrap:wrap}
.livebtn{border:0;border-radius:8px;padding:14px 28px;font:inherit;font-size:16px;font-weight:500;background:var(--red-300);color:#fff;cursor:pointer;transition:background .18s var(--ease)}
.livebtn:hover{background:#BE2330}
.livebtn:active{background:#8F1A24}

/* ---------- grid demo ---------- */
.gridwrap{position:relative;border:1px solid var(--border-secondary);border-radius:16px;overflow:hidden;background:var(--neutral-75)}
.gridbar{display:flex;gap:2px;height:200px;padding:0 var(--gp,10%);transition:padding .5s var(--ease)}
.gcol{flex:1;background:rgba(238,44,60,.14);border-left:1px solid rgba(238,44,60,.3);border-right:1px solid rgba(238,44,60,.3)}
.gridmeta{display:flex;gap:32px;padding:20px;border-top:1px solid var(--border-primary);font-size:14px;color:var(--text-secondary);flex-wrap:wrap}

/* ---------- type specimen ---------- */
.spec{border-top:1px solid var(--border-primary);padding:20px 0;display:grid;grid-template-columns:1fr auto;gap:24px;align-items:baseline}
.spec .meta{font-size:12px;color:var(--text-tertiary);white-space:nowrap;font-variant-numeric:tabular-nums}

/* ---------- roadmap ---------- */
.road{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--gutter);margin-top:32px}
.stop{border-top:3px solid var(--border-secondary);padding-top:20px}
.stop.done{border-color:var(--neutral-black)}
.stop.here{border-color:var(--red-300)}
.stop .when{font-size:12px;font-weight:600;letter-spacing:1px;text-transform:uppercase;color:var(--text-tertiary);margin-bottom:10px;display:flex;align-items:center;gap:8px}
.stop.here .when{color:var(--text-brand)}
.stop.next{opacity:.5}
.blip{width:8px;height:8px;border-radius:50%;background:var(--red-300);display:inline-block}

/* ---------- outcome ---------- */
.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--gutter)}
.metric{border:1px solid var(--border-secondary);border-radius:16px;padding:28px}
.metric .n{font-size:48px;line-height:1;font-weight:600;font-variant-numeric:tabular-nums}
.metric .k{font-size:14px;color:var(--text-secondary);margin-top:10px;line-height:150%}
.note{background:var(--neutral-75);border-left:3px solid var(--neutral-300);padding:20px 24px;border-radius:0 12px 12px 0;font-size:15px;line-height:160%;color:var(--text-secondary)}

.logo{height:22px;width:auto;display:block}
.flogo{height:30px;margin-bottom:40px;filter:brightness(1.08)}

/* ---------- shipped strip ---------- */
.strip{display:flex;gap:20px;overflow-x:auto;padding:4px var(--margin) 24px;scroll-snap-type:x mandatory;scrollbar-width:thin}
.strip figure{flex:0 0 66%;max-width:900px;scroll-snap-align:center;margin:0}
.strip img{width:100%;height:auto;display:block;border-radius:16px;border:1px solid var(--border-primary);background:var(--neutral-75)}
.strip figcaption{margin-top:12px;font-size:14px;line-height:150%;color:var(--text-secondary)}
@media (max-width:900px){.strip figure{flex:0 0 88%}}

/* ---------- footer ---------- */
footer{background:var(--neutral-black);color:var(--neutral-400);padding:80px 0;margin-top:120px}
footer .fgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:var(--gutter)}
footer h6{font-size:12px;font-weight:600;letter-spacing:1px;text-transform:uppercase;color:var(--neutral-600);margin-bottom:12px}
footer p{font-size:15px;line-height:170%;color:var(--neutral-300)}

/* ---------- responsive ---------- */
@media (max-width:1100px){
  :root{--margin:48px}
  .spine{grid-template-columns:1fr}
  .label{padding-top:0;margin-bottom:8px}
  .faces,.metrics,.road,.glance{grid-template-columns:1fr 1fr}
  footer .fgrid{grid-template-columns:1fr 1fr}
}
@media (max-width:640px){
  :root{--margin:20px}
  .hookline{font-size:34px}
  .h2{font-size:32px}.h3{font-size:26px;letter-spacing:1px}.h4{font-size:24px}
  .faces,.metrics,.road,.glance,.matrix,footer .fgrid{grid-template-columns:1fr}
  .gitem{border-right:0;border-bottom:1px solid var(--border-primary)}
  .section{padding:72px 0}
  .turn{padding:56px 28px}
  .audit{padding:28px}
  .dots{grid-template-columns:repeat(15,1fr)}
  .matrix .hd{display:none}
}

