(function(){
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---------- scroll reveal ---------- */
  var io = new IntersectionObserver(function(es){
    es.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } });
  },{threshold:.12, rootMargin:'0px 0px -60px 0px'});
  document.querySelectorAll('.rv').forEach(function(el){ io.observe(el); });

  /* ---------- token audit dots ---------- */
  var dots = document.getElementById('dots');
  var total = 299, kh = 276;
  for(var i=0;i<total;i++){
    var d = document.createElement('span');
    d.className = 'dot' + (i < kh ? ' kh' : '');
    dots.appendChild(d);
  }
  var auditIO = new IntersectionObserver(function(es){
    es.forEach(function(e){
      if(!e.isIntersecting) return;
      auditIO.unobserve(e.target);
      var all = dots.querySelectorAll('.dot');
      all.forEach(function(d,i){
        if(reduce){ d.classList.add('on'); return; }
        setTimeout(function(){ d.classList.add('on'); }, i * 4);
      });
      e.target.querySelectorAll('[data-to]').forEach(function(n){ countUp(n); });
    });
  },{threshold:.25});
  auditIO.observe(document.getElementById('audit'));

  function countUp(el){
    var to = parseInt(el.getAttribute('data-to'),10);
    if(reduce || to < 5){ el.textContent = to; return; }
    var t0 = null, dur = 1100;
    function step(ts){
      if(!t0) t0 = ts;
      var p = Math.min((ts - t0)/dur, 1);
      el.textContent = Math.round(to * (1 - Math.pow(1-p,3)));
      if(p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }
  var mIO = new IntersectionObserver(function(es){
    es.forEach(function(e){ if(e.isIntersecting){ mIO.unobserve(e.target); e.target.querySelectorAll('[data-to]').forEach(countUp); } });
  },{threshold:.4});
  document.querySelectorAll('.metrics').forEach(function(m){ mIO.observe(m); });

  /* ---------- tab switches ---------- */
  document.querySelectorAll('.switch[data-group]').forEach(function(sw){
    sw.addEventListener('click', function(ev){
      var b = ev.target.closest('button'); if(!b) return;
      sw.querySelectorAll('button').forEach(function(x){ x.setAttribute('aria-selected', x===b); });
      if(b.dataset.pane){
        var scope = sw.parentElement;
        scope.querySelectorAll('.pane').forEach(function(p){
          p.classList.toggle('on', p.dataset.pane === b.dataset.pane);
        });
      }
      if(b.dataset.grid) drawGrid(b.dataset.grid);
    });
  });

  /* ---------- token tables ---------- */
  var TOK = {
    text:[
      ['text-primary','#000000','neutral/black'],
      ['text-secondary','#717171','neutral/500'],
      ['text-tertiary','#A5A5A5','neutral/400'],
      ['text-inverse-primary','#FFFFFF','neutral/white'],
      ['text-brand','#EE2C3C','red/300'],
      ['text-success','#28AC52','green/400'],
      ['text-caution','#F5C81C','yellow/400'],
      ['text-error','#DC2132','red/400']
    ],
    surface:[
      ['surface-bg','#FFFFFF','neutral/white'],
      ['surface-surface','#F2F2F2','neutral/100'],
      ['surface-brand','#EE2C3C','red/300'],
      ['surface-success','#C8F5D4','green/100'],
      ['surface-caution','#FEF6C3','yellow/100'],
      ['surface-error','#FDCDD2','red/100']
    ],
    button:[
      ['button-primary','#EE2C3C','red/300'],
      ['button-primary-hover','#BE2330','red/600'],
      ['button-primary-pressed','#8F1A24','red/700'],
      ['button-secondary','#E8E8E8','neutral/200'],
      ['button-secondary-hover','#D9D9D9','neutral/300'],
      ['button-secondary-pressed','#A5A5A5','neutral/400'],
      ['button-secondary-accent','#000000','neutral/black'],
      ['button-secondary-accent-hover','#393939','neutral/700'],
      ['button-secondary-accent-pressed','#555555','neutral/600'],
      ['button-disabled','#D9D9D9','neutral/300']
    ]
  };
  Object.keys(TOK).forEach(function(k){
    var tb = document.getElementById('t-'+k);
    TOK[k].forEach(function(r){
      var tr = document.createElement('tr');
      tr.innerHTML = '<td>'+r[0]+'</td>'
        + '<td><span class="sw" style="background:'+r[1]+'"></span></td>'
        + '<td><span class="hex">'+r[1]+'</span></td>'
        + '<td class="alias"><span class="arrow">→</span>'+r[2]+'</td>';
      tb.appendChild(tr);
    });
  });

  /* ---------- type specimens ---------- */
  var SPEC = [
    ['Heading 1','Aa Learning that compounds','h1','Medium · 51 · 100% · 0'],
    ['Heading 1 Accent','Aa Learning that compounds','h1 accent','Fraunces SemiBold Italic · 51 · 100%'],
    ['Heading 3','Aa Learning that compounds','h3','Medium · 36 · 120% · 2px'],
    ['Heading 5','Aa Learning that compounds','h5','SemiBold · 24 · 120% · 0'],
    ['Body Large','Aa Learning that compounds','bodyL','Regular · 18 · 140% · 0'],
    ['Body','Aa Learning that compounds','body','Regular · 16 · 140% · -0.25px'],
    ['Body Small','Aa Learning that compounds','bodyS','Regular · 14 · 140% · 0']
  ];
  var sp = document.getElementById('specimens');
  SPEC.forEach(function(s){
    var d = document.createElement('div');
    d.className = 'spec';
    d.innerHTML = '<div><div class="bodyXS dimmer" style="letter-spacing:1px;text-transform:uppercase;margin-bottom:8px">'+s[0]
      +'</div><div class="'+s[2]+'">'+s[1]+'</div></div><div class="meta">'+s[3]+'</div>';
    sp.appendChild(d);
  });

  /* ---------- grid demo ---------- */
  var bar = document.getElementById('gridbar'), meta = document.getElementById('gridmeta');
  function drawGrid(mode){
    var cols = mode === 'phone' ? 4 : 12;
    bar.innerHTML = '';
    bar.style.gap = mode === 'phone' ? '16px' : '24px';
    bar.style.setProperty('--gp', mode === 'phone' ? '5%' : '8.3%');
    for(var i=0;i<cols;i++){
      var c = document.createElement('div'); c.className='gcol'; bar.appendChild(c);
    }
    meta.innerHTML = mode === 'phone'
      ? '<span><strong>Phone</strong> 360 × 800</span><span>4 columns</span><span>17 and 18px margins</span><span>16px gutters</span>'
      : '<span><strong>Desktop</strong> 1440 × 1024</span><span>12 columns</span><span>120px margins</span><span>24px gutters</span>';
  }
  drawGrid('desktop');
})();

upgrad-three-doors.styles:
:root{
  --ground:#f3f2ef; --surface:#ffffff; --ink:#121212; --ink-2:#55534f; --ink-3:#8c8a85; --rule:#dcdad5;
  --red:#e3263a; --red-soft:#fbe2e4;
  --stage:#0d0d0f; --stage-ink:#f2f1ee; --stage-2:#9a9893; --stage-rule:#2a2a2e;
  --display:"Bricolage Grotesque","DM Sans",system-ui,sans-serif;
  --body:"DM Sans",system-ui,sans-serif;
  --mono:"JetBrains Mono",ui-monospace,Menlo,monospace;
  --r:20px; --ease:cubic-bezier(.2,0,0,1);
  --gutter:clamp(16px,4vw,56px);
}
@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]){
    color-scheme:dark;
    --ground:#141413; --surface:#1c1c1b; --ink:#f1efeb; --ink-2:#b3b0aa; --ink-3:#7f7c77; --rule:#2e2d2b;
    --red:#ff4a5b; --red-soft:#3a1a1e;
    --stage:#060607; --stage-rule:#232326;
  }
}
:root[data-theme="dark"]{
  color-scheme:dark;
  --ground:#141413; --surface:#1c1c1b; --ink:#f1efeb; --ink-2:#b3b0aa; --ink-3:#7f7c77; --rule:#2e2d2b;
  --red:#ff4a5b; --red-soft:#3a1a1e;
  --stage:#060607; --stage-rule:#232326;
}
*{box-sizing:border-box}
body{margin:0;background:var(--ground);color:var(--ink);font-family:var(--body);font-size:17px;line-height:1.55;-webkit-font-smoothing:antialiased}
.page{padding-inline:var(--gutter)}
.wrap{max-width:1280px;margin-inline:auto}
a{color:inherit}
:focus-visible{outline:2px solid var(--red);outline-offset:3px;border-radius:6px}
h1,h2,h3{font-family:var(--display);margin:0;text-wrap:balance;letter-spacing:-.02em}
p{margin:0}

/* margin label spine */
.spine{display:grid;grid-template-columns:200px minmax(0,1fr);gap:24px 48px;align-items:start}
.lab{font-family:var(--mono);font-size:12px;line-height:1.4;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3);padding-top:.55em;display:flex;gap:10px;align-items:center}
.lab::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--red);flex:none}
@media (max-width:820px){.spine{grid-template-columns:minmax(0,1fr);gap:12px}}

/* hero */
.top{display:flex;justify-content:space-between;align-items:center;padding-block:28px;font-family:var(--mono);font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3)}
.top b{color:var(--ink);font-weight:500}
.hero{padding-block:clamp(40px,8vw,112px) clamp(40px,6vw,80px)}
.hero h1{font-size:clamp(44px,8.4vw,128px);line-height:.92;font-weight:800;letter-spacing:-.035em}
.hero h1 .lt{font-weight:400;color:var(--ink-3)}
.hero h1 .r{color:var(--red)}
.hero .lede{margin-top:32px;max-width:60ch;font-size:clamp(18px,1.6vw,21px);color:var(--ink-2)}

/* at a glance */
.glance{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-top:1px solid var(--rule);border-bottom:1px solid var(--rule);margin-bottom:clamp(56px,8vw,120px)}
.glance div{padding:18px 20px 20px 0;display:flex;flex-direction:column;gap:6px}
.glance div + div{padding-left:20px;border-left:1px solid var(--rule)}
.glance dt{font-family:var(--mono);font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3)}
.glance dd{margin:0;font-size:15px;line-height:1.45}
@media (max-width:820px){.glance{grid-template-columns:repeat(2,minmax(0,1fr))}.glance div:nth-child(3){padding-left:0;border-left:0}.glance div:nth-child(n+3){border-top:1px solid var(--rule)}}

/* door index */
.doors{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:8px}
.door{display:flex;flex-direction:column;gap:14px;text-decoration:none;padding:22px;border-radius:var(--r);background:var(--surface);border:1px solid var(--rule);transition:border-color .2s var(--ease),transform .2s var(--ease)}
.door:hover{border-color:var(--ink-3);transform:translateY(-2px)}
.door .sw{height:120px;border-radius:12px;position:relative;overflow:hidden}
.door h3{font-size:22px;line-height:1.15;font-weight:600}
.door p{font-size:15px;color:var(--ink-2)}
.door .mode{font-family:var(--mono);font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3);margin-top:auto}
.sw.j{background:#fff;border:1px solid #e6e6e6}
.sw.j::before{content:"";position:absolute;left:0;right:0;top:62%;height:4px;background:#ee2c3c;border-radius:4px;transform:skewY(-6deg)}
.sw.j::after{content:"2012";position:absolute;right:10px;bottom:-14px;font:800 64px/1 var(--display);color:#f2f2f2}
.sw.a{background:radial-gradient(70% 90% at 70% 110%,#ff8a3d 0,#ffb547 18%,transparent 55%),linear-gradient(#080b22,#1c2360)}
.sw.a::before{content:"";position:absolute;inset:0;background-image:radial-gradient(1.2px 1.2px at 20% 30%,#fff 50%,transparent 51%),radial-gradient(1px 1px at 55% 18%,#fff 50%,transparent 51%),radial-gradient(1.4px 1.4px at 80% 40%,#ffd98a 50%,transparent 51%),radial-gradient(1px 1px at 35% 55%,#fff 50%,transparent 51%),radial-gradient(1px 1px at 68% 62%,#fff 50%,transparent 51%)}
.sw.p{background:radial-gradient(40% 60% at 50% 55%,#6a11b0 0,transparent 72%),#000}
.sw.p::before{content:"";position:absolute;top:22px;bottom:22px;left:50%;width:54px;margin-left:-27px;background:#fff;border-radius:6px;box-shadow:-70px 10px 0 -8px #333,70px 10px 0 -8px #333}
@media (max-width:900px){.doors{grid-template-columns:minmax(0,1fr)}}

/* exhibits */
.ex{padding-block:clamp(72px,10vw,150px) 0}
.ex-head h2{font-size:clamp(34px,5vw,68px);line-height:1;font-weight:800}
.ex-head h2 .lt{font-weight:400;color:var(--ink-3)}
.ex-head .desc{margin-top:22px;max-width:62ch;color:var(--ink-2)}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:22px}
.chip{font-family:var(--mono);font-size:11.5px;letter-spacing:.04em;padding:6px 10px;border-radius:99px;border:1px solid var(--rule);color:var(--ink-2)}

/* stage */
.stage{margin-top:clamp(36px,5vw,64px);background:var(--stage);color:var(--stage-ink);border-radius:28px;padding:14px;position:relative}
.bar{display:flex;align-items:center;gap:12px;padding:4px 6px 14px;flex-wrap:wrap}
.dots{display:flex;gap:6px}
.dots i{width:10px;height:10px;border-radius:50%;background:#3a3a3e}
.addr{flex:1;min-width:140px;font-family:var(--mono);font-size:12px;color:var(--stage-2);background:#18181b;border-radius:99px;padding:7px 14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ctrls{display:flex;gap:6px;flex-wrap:wrap}
.seg{display:flex;background:#18181b;border-radius:99px;padding:3px}
.seg button,.btn{font:500 12.5px/1 var(--body);color:var(--stage-2);background:none;border:0;border-radius:99px;padding:8px 13px;cursor:pointer;display:inline-flex;align-items:center;gap:6px;text-decoration:none;transition:color .15s,background .15s}
.seg button[aria-pressed="true"]{background:var(--stage-ink);color:var(--stage)}
.btn{background:#18181b}
.btn:hover,.seg button:hover:not([aria-pressed="true"]){color:var(--stage-ink)}
.btn svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.viewport{display:flex;justify-content:center;background:#000;border-radius:16px;overflow:hidden;transition:padding .35s var(--ease)}
.viewport iframe{display:block;width:100%;height:min(82vh,820px);min-height:520px;border:0;background:#111;transition:width .35s var(--ease),height .35s var(--ease),border-radius .35s var(--ease)}
.stage.phone .viewport{padding:28px 0;background:radial-gradient(60% 70% at 50% 50%,#1b1b1f,#000)}
.stage.phone iframe{width:min(390px,100%);height:min(780px,82vh);border-radius:36px;box-shadow:0 0 0 10px #222,0 30px 80px rgba(0,0,0,.6)}
.hint{padding:12px 8px 4px;font-size:13px;color:var(--stage-2);display:flex;gap:8px;align-items:center}
.hint kbd{font-family:var(--mono);font-size:11px;border:1px solid var(--stage-rule);border-radius:5px;padding:1px 6px;color:var(--stage-ink)}
@media (max-width:700px){.stage{border-radius:20px;padding:8px}.viewport iframe{height:72vh;min-height:460px}.addr{display:none}.stage.phone .viewport{padding:0;background:#000}.stage.phone iframe{border-radius:0;box-shadow:none;width:100%}}

/* flow */
.flow{margin-top:clamp(40px,6vw,72px)}
.steps{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:0;border-top:1px solid var(--rule)}
.steps li{padding:20px 20px 24px 0;display:flex;flex-direction:column;gap:8px;border-bottom:1px solid var(--rule)}
.steps .n{font-family:var(--mono);font-size:12px;color:var(--red);font-variant-numeric:tabular-nums}
.steps h3{font-size:19px;line-height:1.2;font-weight:600;letter-spacing:-.01em}
.steps p{font-size:15px;color:var(--ink-2)}
.steps button{align-self:flex-start;margin-top:4px;font:500 13px/1 var(--body);color:var(--ink);background:none;border:1px solid var(--rule);border-radius:99px;padding:7px 12px;cursor:pointer}
.steps button:hover{border-color:var(--ink-3)}

/* compare */
.compare{padding-block:clamp(88px,12vw,170px) clamp(40px,6vw,80px)}
.compare h2{font-size:clamp(32px,4.4vw,58px);line-height:1.02;font-weight:800}
.compare h2 .lt{font-weight:400;color:var(--ink-3)}
.tbl{overflow-x:auto;margin-top:40px}
table{width:100%;min-width:720px;border-collapse:collapse;font-size:15px}
th,td{text-align:left;vertical-align:top;padding:16px 18px 16px 0;border-bottom:1px solid var(--rule)}
thead th{font-family:var(--display);font-size:20px;font-weight:600;letter-spacing:-.01em;border-bottom:1px solid var(--ink)}
tbody th{font-family:var(--mono);font-size:11.5px;font-weight:400;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3);width:170px;padding-top:19px}
td{color:var(--ink-2)}

/* system */
.sys{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:40px}
.tok{background:var(--surface);border:1px solid var(--rule);border-radius:var(--r);padding:20px;display:flex;flex-direction:column;gap:14px}
.tok h3{font-size:17px;font-weight:600;letter-spacing:-.01em}
.sws{display:flex;gap:6px}
.sws span{flex:1;height:44px;border-radius:8px;border:1px solid rgba(128,128,128,.25)}
.tok p{font-size:14px;color:var(--ink-2)}
.tok code{font-family:var(--mono);font-size:12px;color:var(--ink-3)}
@media (max-width:900px){.sys{grid-template-columns:minmax(0,1fr)}}

footer{padding-block:48px 64px;margin-top:clamp(64px,8vw,120px);border-top:1px solid var(--rule);display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;font-family:var(--mono);font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3)}

@media (prefers-reduced-motion:reduce){*{transition:none!important}}

scripts.code:
(() => {
  document.querySelectorAll('[data-stage]').forEach(stage => {
    const frame = stage.querySelector('iframe');
    const src = frame.getAttribute('src');
    stage.querySelectorAll('[data-vp]').forEach(b => b.addEventListener('click', () => {
      stage.classList.toggle('phone', b.dataset.vp === 'phone');
      stage.querySelectorAll('[data-vp]').forEach(x => x.setAttribute('aria-pressed', x === b));
    }));
    stage.querySelector('[data-reload]').addEventListener('click', () => { frame.src = 'about:blank'; setTimeout(() => frame.src = src, 30); });
  });

  // After Hours route jumps
  const ah = document.querySelector('#afterhours iframe');
  const base = ah.getAttribute('src');
  document.querySelectorAll('[data-route]').forEach(b => b.addEventListener('click', () => {
    const route = b.dataset.route;
    ah.scrollIntoView({behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'center'});
    let done = false;
    try {
      const w = ah.contentWindow;
      if (w && w.location.href !== 'about:blank') { w.location.hash = route; done = true; }
    } catch (e) {}
    if (!done) ah.src = base + route;
    if (b.hasAttribute('data-open-first')) {
      setTimeout(() => {
        try {
          const d = ah.contentDocument;
          const link = d && d.querySelector('a[href^="#/program/"]');
          if (link) ah.contentWindow.location.hash = link.getAttribute('href');
        } catch (e) {}
      }, 900);
    }
  }));
})();
